#!/usr/bin/env python3
"""Prepare, compare and export retained Upper Savannah receiving waters."""
from __future__ import annotations
import argparse
import json
from pathlib import Path
import sys
if __package__ in (None, ""):
    sys.path.insert(0, str(Path(__file__).resolve().parent.parent))
    __package__ = "model"
from .common import read_json
from .workspace import Workspace
from . import receiving_waters, receiving_water_delivery


def parser():
    command = argparse.ArgumentParser(description=__doc__)
    command.add_argument("--workspace", type=Path, required=True)
    operations = command.add_subparsers(dest="operation", required=True)
    for name, help_text in (
        ("prepare", "Create a source-only receptor plan"),
        ("profile", "Use the shared utility-focus receptor profile"),
        ("analyze", "Analyze completed original baseline and land-cover runs"),
        ("build", "Resolve a plan, analyze runs and export a complete receiving-water delivery"),
    ):
        selected = operations.add_parser(name, help=help_text)
        selected.add_argument("selection", type=Path)
        if name == "profile":
            selected.add_argument("--grid-id")
        if name == "build":
            selected.add_argument("--output-dir", type=Path)
    for name in ("plan", "analysis", "layers"):
        operations.add_parser(name).add_argument("id")
    listing = operations.add_parser("list")
    listing.add_argument("kind", choices=("plans", "analyses", "all"), default="all", nargs="?")
    export = operations.add_parser("export")
    export.add_argument("analysis_id")
    export.add_argument("output_dir", type=Path)
    return command


def main(argv=None):
    args = parser().parse_args(argv)
    workspace = Workspace(args.workspace)
    progress = lambda value: print(json.dumps(value, sort_keys=True), file=sys.stderr, flush=True)
    if args.operation == "prepare":
        result = receiving_waters.prepare(workspace, read_json(args.selection))
    elif args.operation == "profile":
        result = receiving_waters.prepare_receptor_spec(
            workspace, read_json(args.selection), grid_id=args.grid_id,
        )
    elif args.operation == "analyze":
        result = receiving_waters.analyze(workspace, read_json(args.selection), progress=progress)
    elif args.operation == "build":
        selection = read_json(args.selection)
        result = receiving_water_delivery.selected_analysis(workspace, selection, progress=progress)
        if result is None:
            raise ValueError("The build selection requires its receiving_waters source plan or analysis")
        if args.output_dir:
            result = receiving_water_delivery.export(workspace, result["id"], args.output_dir)
    elif args.operation == "plan":
        result = receiving_waters.inspect_plan(workspace, args.id)
    elif args.operation == "analysis":
        result = receiving_waters.inspect(workspace, args.id)
    elif args.operation == "layers":
        result = receiving_waters.delivery_layers(workspace, args.id)
    elif args.operation == "export":
        result = receiving_water_delivery.export(workspace, args.analysis_id, args.output_dir)
    else:
        result = {}
        if args.kind in ("plans", "all"):
            result["plans"] = receiving_waters.list_plans(workspace)
        if args.kind in ("analyses", "all"):
            result["analyses"] = receiving_waters.list_analyses(workspace)
    print(json.dumps(result, ensure_ascii=False, allow_nan=False, indent=2))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

"""Join receiving-water analyses to the existing seven-map delivery."""
from __future__ import annotations
import json
from pathlib import Path
import shutil
from .common import (
    atomic_json, describe_file, file_digest, identifier, read_json, verify_file,
)
from . import rasters, receiving_waters


def selected_analysis(workspace, selection, *, priority_settings=None, progress=None):
    """Resolve one explicit receiving_waters selection to completed quantities.

    selection is the existing delivery request. The nested receiving_waters
    record chooses analysis_id, plan_id, plan or receptor_spec. An explicit
    analysis is reused only with the same selected baseline and alternatives.
    """
    choice = selection.get("receiving_waters")
    if choice is None:
        return None
    if not isinstance(choice, dict):
        raise ValueError("Receiving-water delivery selection must be an object")
    baseline_id = identifier(selection["baseline_run_id"])
    alternatives = list(selection.get("scenario_run_ids", selection.get("alternative_run_ids", [])))
    baseline = workspace.inspect_run(baseline_id)
    keys = [name for name in ("analysis_id", "plan_id", "plan", "receptor_spec") if choice.get(name) is not None]
    if len(keys) != 1:
        raise ValueError("Select exactly one receiving-water analysis, plan or source profile")
    if keys[0] == "analysis_id":
        result = receiving_waters.inspect(workspace, choice["analysis_id"])
        if result.get("state") != "complete":
            raise ValueError("Complete the selected receiving-water analysis")
        if result["baseline_run_id"] != baseline_id or set(result["alternative_run_ids"]) != set(alternatives):
            raise ValueError("Receiving-water analysis must match the delivery baseline and alternatives")
        if choice.get("quantity_scope") and result["quantity_scope"] != choice["quantity_scope"]:
            raise ValueError("Selected receiving-water quantity scope differs from the retained analysis")
        return result
    if keys[0] == "plan_id":
        plan_id = identifier(choice["plan_id"])
    elif keys[0] == "plan":
        plan_id = receiving_waters.prepare(workspace, choice["plan"])["id"]
    else:
        plan_id = receiving_waters.prepare_receptor_spec(
            workspace, choice["receptor_spec"], grid_id=baseline["selection"]["grid_id"],
        )["id"]
    request = {
        "plan_id": plan_id, "baseline_run_id": baseline_id,
        "alternative_run_ids": alternatives,
        "quantity_scope": choice.get("quantity_scope", "reporting"),
    }
    for name in ("title", "weights", "normalization", "pollutants"):
        if name in choice:
            request[name] = choice[name]
    if priority_settings and "normalization" not in request:
        quantities = request.get("pollutants") or [key for key in rasters.MASS_UNITS if key in baseline["artifacts"]]
        request["normalization"] = {
            "method": "explicit", "caps": {key: priority_settings["caps"][key] for key in quantities},
            "reference": {
                "kind": "selected baseline delivery priority",
                "baseline_run_id": baseline_id,
                "method": priority_settings["method"],
                "percentile": priority_settings.get("percentile"),
            },
        }
        request.setdefault("weights", {key: priority_settings["weights"][key] for key in quantities})
    return receiving_waters.analyze(workspace, request, progress=progress)


def _copy_member(source_root, item, directory, prefix):
    original = verify_file(source_root, item)
    target = directory / prefix / item["path"]
    target.parent.mkdir(parents=True, exist_ok=True)
    if target.exists():
        if target.stat().st_size != item["bytes"] or file_digest(target) != item["sha256"]:
            raise ValueError("A retained receiving-water delivery member changed: " + str(target))
    else:
        shutil.copyfile(original, target)
    result = {**item, **describe_file(directory, target)}
    if result["bytes"] != item["bytes"] or result["sha256"] != item["sha256"]:
        raise ValueError("Receiving-water delivery copy differs from its original")
    return result


def export(workspace, analysis_id, directory):
    """Export complete source plan, analysis and files to a self-contained folder."""
    analysis = receiving_waters.inspect(workspace, analysis_id)
    if analysis["state"] != "complete":
        raise ValueError("Complete the selected receiving-water analysis for export")
    plan = receiving_waters.inspect_plan(workspace, analysis["plan_id"])
    directory = Path(directory)
    directory.mkdir(parents=True, exist_ok=True)
    analysis_root = workspace.root / "receiving-water-analyses" / analysis["id"]
    plan_root = workspace.root / "receiving-water-plans" / plan["id"]
    identity = {
        "analysis_id": analysis["id"], "analysis_record_sha256": analysis["record_sha256"],
        "plan_id": plan["id"], "plan_record_sha256": plan["record_sha256"],
    }
    index_path = directory / "receiving-water-delivery.json"
    if index_path.exists():
        retained = read_json(index_path)
        if retained["identity"] != identity:
            raise ValueError("Choose a separate export directory for another receiving-water selection")
        for item in retained["files"].values():
            verify_file(directory, item)
        return retained
    files = {}
    for name, item in analysis["files"].items():
        files["analysis_" + name] = _copy_member(analysis_root, item, directory, "analysis")
    for name, item in plan["files"].items():
        files["plan_" + name] = _copy_member(plan_root, item, directory, "plan")
    files["analysis_record"] = _copy_member(
        analysis_root, describe_file(analysis_root, analysis_root / "analysis.json"), directory, "analysis",
    )
    files["plan_record"] = _copy_member(
        plan_root, describe_file(plan_root, plan_root / "plan.json"), directory, "plan",
    )
    def exported(item):
        return {**item, "path": "analysis/" + item["path"]} if item else None
    original_layers = receiving_waters.delivery_layers(workspace, analysis["id"])
    families = {}
    for family, row in original_layers["families"].items():
        families[family] = {
            **row,
            "current_priority": exported(row["current_priority"]),
            "contribution_mask": exported(row["contribution_mask"]),
            "alternatives": {
                run_id: {
                    **alternative,
                    **{name: exported(alternative[name]) for name in
                       ("current_priority", "increased_export_priority", "avoided_export_priority")},
                    "physical_changes": {name: exported(item)
                                         for name, item in alternative["physical_changes"].items()},
                }
                for run_id, alternative in row["alternatives"].items()
            },
        }
    result = {
        "schema": "upstate.receiving-water-delivery/v1", "identity": identity,
        "title": analysis["title"], "baseline_run_id": analysis["baseline_run_id"],
        "alternative_run_ids": analysis["alternative_run_ids"],
        "quantity_scope": analysis["quantity_scope"], "pollutants": analysis.get("pollutants", list(rasters.MASS_UNITS)),
        "normalization": analysis["normalization"],
        "families": families, "files": files, "measurement": analysis["measurement"],
        "receptors": [
            {"id": row["id"], "title": row["title"], "family": row["family"],
             "relationship_precision": row["relationship_precision"],
             "source": row["source"], "classification": row["classification"],
             "contribution_area_ha": row["contribution_area_ha"],
             "area_in_quantity_scope_ha": row["area_in_quantity_scope_ha"],
             "metrics": {**row["metrics"], "files": {
                 name: exported(item) for name, item in row["metrics"]["files"].items()
             }}}
            for row in analysis["subjects"] if row["kind"] == "receptor"
        ],
    }
    atomic_json(index_path, result)
    return result


def collect(workspace, selection, directory, *, priority_settings=None, progress=None):
    """Return delivery inventory and actual attributed overlays for selected waters."""
    analysis = selected_analysis(
        workspace, selection, priority_settings=priority_settings, progress=progress,
    )
    if analysis is None:
        return None
    directory = Path(directory)
    inventory = export(workspace, analysis["id"], directory)
    prepared = workspace.get_grid(workspace.inspect_run(analysis["baseline_run_id"])["selection"]["grid_id"])
    overlay_path = verify_file(directory, inventory["files"]["analysis_receiving_waters_gpkg"])
    overlays = {}
    for family, row in inventory["families"].items():
        if row["current_priority"] is None:
            continue
        selected, _ = rasters.vector_geometry(
            overlay_path, layer="receiving_waters", target_crs=prepared["grid"]["crs"],
            where={"kind": "family_union", "family": family},
        )
        overlays[family] = {
            "label": row["title"] + " / " + inventory["quantity_scope"].replace("_", " "),
            "features": selected, "width": 0.8, "style": "--",
            "source": {"analysis_id": analysis["id"], "plan_id": analysis["plan_id"],
                       "method": row["relationship_precision"]},
        }
    return {"inventory": inventory, "overlays": overlays, "directory": str(directory)}


def attach_state(state, delivery_directory, product):
    """Add original copied artifacts to the existing delivery state."""
    if product is None:
        return
    directory, delivery_directory = Path(product["directory"]), Path(delivery_directory)
    inventory = product["inventory"]
    state["receiving_waters"] = {
        "identity": inventory["identity"], "quantity_scope": inventory["quantity_scope"],
        "pollutants": inventory["pollutants"],
        "artifact_root": directory.relative_to(delivery_directory).as_posix(),
        "normalization": inventory["normalization"], "families": inventory["families"],
        "measurement": inventory["measurement"],
        "report_sections": report_section(product),
    }
    for name, item in inventory["files"].items():
        state["files"]["receiving_water_" + name] = describe_file(
            delivery_directory, verify_file(directory, item),
        )
    state["files"]["receiving_water_index"] = describe_file(
        delivery_directory, directory / "receiving-water-delivery.json",
    )


def apply_map_specs(specifications, product):
    """Replace configured protection-family panels with their own physical priorities."""
    if product is None:
        return
    directory = Path(product["directory"])
    for family, row in product["inventory"]["families"].items():
        artifact = row["current_priority"]
        if artifact is None:
            continue
        existing_panels, existing_overlays = specifications.get(family, ([], []))
        previous = dict(existing_panels[0]) if existing_panels else {}
        units = previous.get("units", "dimensionless (0-1)")
        own_overlay = product["overlays"].get(family)
        specifications[family] = (
            [{**previous, "path": verify_file(directory, artifact),
              "label": "Current export priority in selected receiving-water land",
              "units": units, "signed": False,
              "scale": {"minimum": 0.0, "maximum": 1.0, "signed": False,
                        "units": units,
                        "label": "Fixed 0-1 range for the selected receiving-water priority."}}],
            existing_overlays + ([own_overlay] if own_overlay else []),
        )


def report_section(product):
    """A scientific-report section using actual per-water quantities and source methods."""
    if product is None:
        return []
    inventory = product["inventory"]
    paragraphs = [
        "Receiving-water physical quantities use the " + inventory["quantity_scope"].replace("_", " ")
        + " scope. Each family uses its actual selected contribution footprint.",
        "Fixed pollutant normalization: " + json.dumps(inventory["normalization"], sort_keys=True),
        inventory["measurement"]["physical"],
        inventory["measurement"]["coverage"],
        inventory["measurement"]["overlap"],
    ]
    for row in inventory["receptors"]:
        metrics = row["metrics"]
        summary = {
            "title": row["title"], "family": row["family"],
            "relationship": row["relationship_precision"],
            "selected_cells": metrics["selected_cells"],
            "annual_exports": {
                pollutant: {name: value[name] for name in ("sum", "sum_units", "valid_cells", "coverage_fraction")}
                for pollutant, value in metrics["baseline_physical"].items()
            },
            "alternative_changes": {
                run_id: {pollutant: {name: value[name] for name in
                                    ("sum", "sum_units", "sum_increased_export", "sum_avoided_export",
                                     "valid_cells", "coverage_fraction")}
                         for pollutant, value in alternative["changes"].items()}
                for run_id, alternative in metrics["alternatives"].items()
            },
        }
        paragraphs.append(json.dumps(summary, ensure_ascii=False, sort_keys=True))
    return [("Receiving-water quantities and priorities", paragraphs)]


def extend_assets(manifest, state):
    """Include the complete receiving-water files in the normal delivery package."""
    assets = manifest["project_assets"]
    selected = {item for item in assets}
    for name, item in state["files"].items():
        if name.startswith("receiving_water_") and item["path"] not in selected:
            assets.append(item["path"])
            selected.add(item["path"])

"""Register retained receiving-water artifacts in the existing SpatialReview.

This module only indexes original saved records. SpatialReview opens and verifies
each exact file when it is used; no vector materialization or raster scan occurs
during catalog enumeration.
"""
from __future__ import annotations

from .common import digest
from . import receiving_waters


PLAN_GROUP = "receiving-water-plan"
ANALYSIS_GROUP = "receiving-water-analysis"


def manifest_paths(workspace):
    """Return the exact record paths that invalidate the spatial catalog."""
    paths = list((workspace.root / "receiving-water-plans").glob("*/plan.json"))
    paths.extend(
        (workspace.root / "receiving-water-analyses").glob("*/analysis.json")
    )
    return sorted(paths)


def _source_metadata(source):
    """Keep compact original source identity without copying feature/HUC lists."""
    if not isinstance(source, dict):
        return {}
    result = {}
    for source_key, target_key in (
        ("source_collection_id", "source_collection_id"),
        ("source_id", "source_id"),
        ("uri", "source_uri"),
        ("vintage", "vintage"),
        ("body_sha256", "source_body_sha256"),
    ):
        if source.get(source_key) is not None:
            result[target_key] = source[source_key]
    if isinstance(source.get("selection"), dict):
        result["source_selection_id"] = digest(source["selection"])
    return result


def _subject_metadata(subject):
    result = {
        "subject_id": subject["id"],
        "subject_kind": subject.get("kind", "receptor"),
        "subject_title": subject["title"],
        "family": subject["family"],
        "relationship_precision": subject["relationship_precision"],
    }
    method = subject.get("relation", {}).get("method")
    if method is not None:
        result["relationship_method"] = method
    result.update(_source_metadata(subject.get("source")))
    return result


def _run_metadata(analysis, run_id):
    identity = analysis["identity"]
    if run_id == analysis["baseline_run_id"]:
        selection = identity.get("baseline_selection", {})
    else:
        selection = identity.get("alternative_selections", {}).get(run_id, {})
    result = {"run_id": run_id}
    for name in ("grid_id", "profile_id", "scenario_id", "invest_version"):
        if selection.get(name) is not None:
            result[name] = selection[name]
    return result


def _subject_rasters(analysis, subject):
    """Yield known original artifact roles with their actual run and quantity."""
    files = subject["metrics"].get("files", {})
    baseline_id = analysis["baseline_run_id"]
    for statistic in ("contribution_mask", "current_priority"):
        item = files.get(statistic)
        if item is not None:
            yield statistic, item, statistic, baseline_id, None, None
    pollutants = analysis.get("pollutants")
    if pollutants is None:
        pollutants = analysis["identity"].get("pollutants")
    if pollutants is None:
        pollutants = list(subject["metrics"].get("baseline_physical", {}))
    for run_id in analysis.get("alternative_run_ids", []):
        for statistic, direction in (
            ("current_priority", None),
            ("increased_export_priority", "positive alternative minus baseline"),
            ("avoided_export_priority", "positive baseline minus alternative"),
        ):
            role = run_id + "_" + statistic
            item = files.get(role)
            if item is not None:
                yield role, item, statistic, run_id, None, direction
        for quantity in pollutants:
            role = run_id + "_" + quantity + "_change"
            item = files.get(role)
            if item is not None:
                yield (
                    role, item, "change", run_id, quantity,
                    "alternative minus baseline",
                )


def _plan_layers(workspace, path, add):
    plan = receiving_waters.inspect_plan(
        workspace, path.parent.name, verify=False,
    )
    if plan.get("state") != "complete":
        return 0
    count = 0
    for receptor in plan["receptors"]:
        metadata = {
            "receiving_water_plan_id": plan["id"],
            **_subject_metadata(receptor),
        }
        for key, geometry_role, label in (
            ("receptor_geometry", "receptor", "Original receiving-water feature"),
            ("contribution_geometry", "contribution", "Selected contribution area"),
        ):
            add(
                PLAN_GROUP, plan["id"],
                "receptor/" + receptor["id"] + "/" + key, receptor[key],
                kind="vector", scope=path.parent,
                title=receptor["title"] + " / " + label,
                native_layer="receiving_water",
                geometry_role=geometry_role,
                statistic=key,
                **metadata,
            )
            count += 1
    return count


def _analysis_layers(workspace, path, add):
    analysis = receiving_waters.inspect(
        workspace, path.parent.name, verify=False,
    )
    if analysis.get("state") != "complete":
        return 0, 0
    shared = {
        "receiving_water_plan_id": analysis["plan_id"],
        "receiving_water_analysis_id": analysis["id"],
        "baseline_run_id": analysis["baseline_run_id"],
        "quantity_scope": analysis["quantity_scope"],
        "grid_id": analysis["identity"]["grid_id"],
        "normalization_id": digest(analysis["normalization"]),
    }
    vector_count = raster_count = 0
    summary = analysis.get("files", {}).get("receiving_waters_gpkg")
    if summary is not None:
        add(
            ANALYSIS_GROUP, analysis["id"], "receiving_waters_gpkg", summary,
            kind="vector", scope=path.parent,
            title=analysis["title"] + " / Receiving-water quantities",
            native_layer="receiving_waters", statistic="physical_summary",
            run_id=analysis["baseline_run_id"], **shared,
        )
        vector_count += 1
    for subject in analysis["subjects"]:
        metadata = {**shared, **_subject_metadata(subject)}
        stem = "subject/" + subject["kind"] + "/" + subject["id"] + "/"
        for role, item, statistic, run_id, quantity, direction in _subject_rasters(
            analysis, subject,
        ):
            layer_metadata = {
                **metadata, **_run_metadata(analysis, run_id),
                "statistic": statistic,
            }
            if run_id != analysis["baseline_run_id"]:
                layer_metadata["alternative_run_id"] = run_id
            if quantity is not None:
                layer_metadata["quantity"] = quantity
            if direction is not None:
                layer_metadata["direction"] = direction
            label = {
                "contribution_mask": "Selected contribution cells",
                "current_priority": "Current export priority",
                "increased_export_priority": "Increased export priority",
                "avoided_export_priority": "Avoided export priority",
                "change": (quantity or "").replace("_", " ") + " change",
            }[statistic]
            run_label = (
                "baseline" if run_id == analysis["baseline_run_id"]
                else "alternative " + run_id[:12]
            )
            add(
                ANALYSIS_GROUP, analysis["id"], stem + role, item,
                kind="raster", scope=path.parent,
                title=subject["title"] + " / " + label + " / " + run_label,
                **layer_metadata,
            )
            raster_count += 1
    return vector_count, raster_count


def add_layers(workspace, add):
    """Register completed saved plans and analyses through SpatialReview.add.

    Callback: add(group, owner_id, role, original_file_descriptor, *,
                  kind, title, scope, native_layer=None, **metadata).

    Artifact dictionaries and physical units pass through unchanged. The native
    spatial reader verifies bytes/digest when opening each scoped file. Original
    manifest identity and project membership are checked by inspect_plan/inspect.
    Failed or unfinished analyses do not become selectable spatial results.
    """
    counts = {"plan_vectors": 0, "analysis_vectors": 0, "analysis_rasters": 0}
    for path in manifest_paths(workspace):
        if path.name == "plan.json":
            counts["plan_vectors"] += _plan_layers(workspace, path, add)
        else:
            vectors, rasters = _analysis_layers(workspace, path, add)
            counts["analysis_vectors"] += vectors
            counts["analysis_rasters"] += rasters
    return counts

"""Read retained station inventories without changing their original source files.

Known normalized assessment banks retain their record-array identity, publisher
record identity and publisher-source hash independently of the imported body hash.
"""
from __future__ import annotations
import csv
import gzip
import json
from pathlib import Path

SCHEMA="upstate.water-quality-assessments/v1"
PUBLISHED_BANKS=(
    {"sha256":"69e6894001fdcfa0130d8be532a31655eda22486a4044079665e8ee614eb5b0c",
     "vintage":"2024","record_count":108},
    {"sha256":"cceaf00eb0fc4cc85eabb67fbd2a9b5d843bb0cc0c7ab8da54d2108f025c2522",
     "vintage":"2026-07-28","record_count":84},
)

def _same(left,right):
    if isinstance(left,bool) or isinstance(right,bool):
        return type(left) is type(right) and left==right
    return left==right

def _selected(original,reference):
    for key,expected in (reference.get("where") or {}).items():
        if key not in original:
            raise ValueError("Original inventory does not contain selected field "+key)
        if not _same(original[key],expected):
            return False
    for key,values in (reference.get("where_in") or {}).items():
        if key not in original:
            raise ValueError("Original inventory does not contain selected field "+key)
        if not isinstance(values,list):
            raise ValueError("Inventory where_in must map original fields to value lists")
        if not any(_same(original[key],expected) for expected in values):
            return False
    return True

def _open(path):
    path=Path(path)
    with path.open("rb") as stream:
        compressed=stream.read(2)==b"\x1f\x8b"
    return gzip.open(path,"rt",encoding="utf-8-sig",newline="") if compressed else path.open(
        encoding="utf-8-sig",newline="")

def read_inventory(path,reference,entry):
    """Return exact selected original dictionaries with stable source positions."""
    for key in ("where","where_in"):
        if reference.get(key) is not None and not isinstance(reference[key],dict):
            raise ValueError("Inventory "+key+" must map original field names to exact values")
    with _open(path) as stream:
        prefix=stream.read(256).lstrip();stream.seek(0)
        if prefix.startswith("{"):
            document=json.load(stream)
            if not isinstance(document,dict) or document.get("schema")!=SCHEMA:
                raise ValueError("Choose a retained upstate.water-quality-assessments/v1 JSON inventory")
            if document.get("complete") is not True or document.get("unparsed_rows"):
                raise ValueError("The original normalized assessment inventory has incomplete source rows")
            records=document.get("records")
            source=document.get("source")
            if not isinstance(records,list) or not isinstance(source,dict):
                raise ValueError("The original assessment inventory needs records and publisher metadata")
            if document.get("row_count",len(records))!=len(records):
                raise ValueError("The original assessment record count differs from its complete array")
            field=reference.get("station_id_field") or entry.get("station_id_field") or "site"
            rows=[];seen=set()
            for index,original in enumerate(records):
                if not isinstance(original,dict):
                    raise ValueError("Each original assessment record must be an object")
                native_id=original.get("id")
                if not isinstance(native_id,str) or not native_id:
                    raise ValueError("Each original assessment record needs its native record ID")
                identity=(original.get("source_id"),original.get("source_sha256"),native_id)
                if not all(isinstance(value,str) and value for value in identity):
                    raise ValueError("Retain publisher source ID, publisher source SHA and native record ID")
                if identity in seen:
                    raise ValueError("Original assessment record identity repeats")
                seen.add(identity)
                if identity[:2]!=(source.get("source_id"),source.get("source_sha256")):
                    raise ValueError("Assessment record publisher identity differs from its original bank")
                if field not in original or not isinstance(original[field],str) or not original[field].strip():
                    raise ValueError("An original assessment record has no exact station identifier")
                if not _selected(original,reference):
                    continue
                rows.append((index+1,original,{"record_index":index,"record_pointer":"/records/"+str(index),
                    "record_id":native_id,"row_number_basis":"original_record_array_one_based",
                    "publisher_source_id":identity[0],"publisher_source_sha256":identity[1],
                    "original_source_row":original.get("source_row"),
                    "original_source_page":original.get("source_page")}))
            return field,rows,{"format":"assessment_json","schema":SCHEMA,
                "original_record_count":len(records),"selected_record_count":len(rows),"publisher":source}
        field=reference.get("station_id_field") or entry.get("station_id_field")
        if not field:
            raise ValueError("Select the exact station field in the original study inventory")
        table=csv.DictReader(stream)
        if not table.fieldnames or len(table.fieldnames)!=len(set(table.fieldnames)) or field not in table.fieldnames:
            raise ValueError("Original station inventory needs distinct headers and its station field")
        rows=[]
        for number,original in enumerate(table,2):
            if None in original:
                raise ValueError("Original station inventory has an extra cell")
            if _selected(original,reference):
                rows.append((number,original,{"row_number_basis":"original_csv_line"}))
        return field,rows,{"format":"csv","fields":table.fieldnames,"selected_record_count":len(rows)}

def catalogue_fields(entry):
    """Recognize declared normalized banks without scanning unrelated source bodies."""
    metadata=entry.get("metadata") or {}
    recognized=(entry.get("schema")==SCHEMA or metadata.get("schema")==SCHEMA or
                entry.get("body",{}).get("sha256") in {row["sha256"] for row in PUBLISHED_BANKS})
    if entry.get("kind")=="table" and recognized:
        return {"station_id_field":entry.get("station_id_field") or "site",
                "inventory_format":"assessment_json","inventory_schema":SCHEMA,
                "inventory_record_identity":"original records[index] and publisher record id",
                "inventory_where_fields":["huc12","source_vintage","publication_status","evidence_kind"]}
    return {}

def published_inventory(workspace,entries,domain):
    """Bind the existing 159-site study directly to both original statewide JSON banks.

    Returning None preserves the existing completed CSV producer as a fallback.
    The publisher HUC selection uses the exact retained original domain identifiers.
    """
    selected=[]
    for spec in PUBLISHED_BANKS:
        matches=[(collection,entry) for collection,entry in entries
                 if entry["kind"]=="table" and entry["body"]["sha256"]==spec["sha256"]]
        if not matches:
            return None
        selected.append((spec,matches[0]))
    if domain is None:
        return None
    path,_=workspace.source_file(domain["collection_id"],domain["source_id"])
    with _open(path) as stream:
        original=json.load(stream)
    field=domain["id_field"]
    features=original.get("features")
    if not isinstance(features,list):
        raise ValueError("The retained assessment domain has no original feature array")
    hucs=[feature.get("attributes",feature.get("properties",{})).get(field) for feature in features]
    if len(hucs)!=217 or len(set(hucs))!=217 or any(
            not isinstance(value,str) or len(value)!=12 or not value.isdigit() for value in hucs):
        raise ValueError("Use the actual retained 217 original HUC12 identifiers")
    references,records,editions=[],[],[]
    for spec,(collection,entry) in selected:
        reference={"collection_id":collection["id"],"source_id":entry["id"],
                   "source_sha256":entry["body"]["sha256"],"station_id_field":"site",
                   "format":"assessment_json","where_in":{"huc12":sorted(hucs)}}
        path,_=workspace.source_file(collection["id"],entry["id"])
        _,rows,info=read_inventory(path,reference,entry)
        originals=[row for _,row,_ in rows]
        if len(originals)!=spec["record_count"] or {row["source_vintage"] for row in originals}!={spec["vintage"]}:
            raise ValueError("The selected original assessment edition differs from its accepted 217-HUC scope")
        references.append(reference);records.extend(originals)
        editions.append({"source_vintage":spec["vintage"],"record_count":len(originals),
                         "station_count":len({row["site"] for row in originals}),
                         "source_id":entry["id"],"source_sha256":entry["body"]["sha256"],
                         "publisher_source_id":info["publisher"]["source_id"],
                         "publisher_source_sha256":info["publisher"]["source_sha256"]})
    if len(records)!=192 or len({row["site"] for row in records})!=159:
        raise ValueError("The original published assessment domain requires 192 records at 159 sites")
    return {"references":references,"records":records,"editions":editions,
            "format":"original_normalized_json","station_count":159,"record_count":192}

#!/usr/bin/env node
import { readFile, writeFile } from "node:fs/promises";
import { resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { createHash } from "node:crypto";
import { reconcile } from "./reconcile.mjs";

const root = resolve(process.argv[2] || fileURLToPath(new URL("../../../", import.meta.url)));
const output = resolve(root, "observations/eighteenmile_2023/cohort_reconciliation_20261013");
const manifest = JSON.parse(await readFile(resolve(output, "source-inputs.json"), "utf8"));
const inputs = {};
for (const input of manifest.files) {
  const bytes = await readFile(resolve(root, input.path));
  const hash = createHash("sha256").update(bytes).digest("hex");
  if (bytes.length !== input.bytes || hash !== input.sha256) throw Error("Original source differs: " + input.path);
  inputs[input.key] = bytes.toString("utf8");
}
const product = reconcile(inputs);
for (const [name,content] of Object.entries(product.files)) await writeFile(resolve(output,name),content,"utf8");
process.stdout.write(JSON.stringify({selected_original_activities:product.selected.length,summary:product.summary},null,2)+"\n");

// Reconcile the original five-site chlorophyll cohort by dates and independent routine-visit evidence.
function csvParse(s){const rows=[];let row=[],cell="",q=false;for(let i=0;i<s.length;i++){let ch=s[i];if(ch==='"'){if(q&&s[i+1]==='"'){cell+='"';i++;}else q=!q;}else if(ch===","&&!q){row.push(cell);cell="";}else if((ch==="\n"||ch==="\r")&&!q){if(ch==="\r"&&s[i+1]==="\n")i++;row.push(cell);rows.push(row);row=[];cell="";}else cell+=ch;}if(cell||row.length){row.push(cell);rows.push(row);}const hdr=rows.shift();return rows.filter(x=>x.length===hdr.length).map(x=>Object.fromEntries(hdr.map((h,i)=>[h,x[i]])));}

function csvString(rows, columns) {
  const quote = value => /[",\r\n]/.test(String(value ?? "")) ? '"' + String(value ?? "").replaceAll('"', '""') + '"' : String(value ?? "");
  return [columns, ...rows.map(row => columns.map(key => row[key]))].map(row => row.map(quote).join(",")).join("\n") + "\n";
}

const CHLOROPHYLL = "Chlorophyll a, corrected for pheophytin";
const EXCLUDED = [
  {site_id:"SV-268",date:"2023-07-11",routine_time:"13:08:00",routine_activity_id:"21SC60WQ_WQX-AF05218",
   chlorophyll_activity_id:"21SC60WQ_WQX-SV-268:20230711130800:SR:0.3:WB",study_time:"09:50:00",routine_value:"22.77",study_value:"15.76",day_input:"sv268day"},
  {site_id:"SV-374",date:"2023-08-08",routine_time:"10:59:00",routine_activity_id:"21SC60WQ_WQX-AF06949",
   chlorophyll_activity_id:"21SC60WQ_WQX-SV-374:20230808105900:SR:0.3:WB",study_time:"10:54:00",routine_value:"8.64",study_value:"10.91",day_input:"sv374day"},
];
const PUBLISHED = {
  "SV-268":{mean:7.4,sd:8.0,minimum:1.2,maximum:28.6,n_reported:15},
  "SV-838":{mean:24.1,sd:8.6,minimum:12.4,maximum:38.9,n_reported:15},
  "SV-839":{mean:15.4,sd:7.4,minimum:7.5,maximum:31.3,n_reported:15},
  "SV-374":{mean:10.7,sd:4.3,minimum:5.6,maximum:18.7,n_reported:4},
  "SV-840":{mean:6.1,sd:1.8,minimum:3.4,maximum:8.6,n_reported:4},
};

function recordReference(row) {
  return {activity_id:row.ActivityIdentifier,project_identifier:row.ProjectIdentifier,
    site_id:row.MonitoringLocationIdentifier,date:row.ActivityStartDate,
    time:row["ActivityStartTime/Time"],timezone:row["ActivityStartTime/TimeZoneCode"],
    depth:row["ActivityDepthHeightMeasure/MeasureValue"],depth_unit:row["ActivityDepthHeightMeasure/MeasureUnitCode"],
    characteristic:row.CharacteristicName,value:row.ResultMeasureValue,unit:row["ResultMeasure/MeasureUnitCode"],
    method:row["ResultAnalyticalMethod/MethodIdentifier"]};
}

function reconcile(inputs) {
  const three = csvParse(inputs.three).filter(row => row.CharacteristicName === CHLOROPHYLL);
  const two = csvParse(inputs.two).filter(row => row.CharacteristicName === CHLOROPHYLL);
  const dates = [...new Set(three.map(row => row.ActivityStartDate))].sort();
  if (dates.length !== 15 || three.length !== 45) throw Error("Expected the original three-site, fifteen-date lake cohort");
  for (const site of ["SV-838","SV-839","SV-840"]) {
    const rows = three.filter(row => row.MonitoringLocationIdentifier === "21SC60WQ_WQX-" + site);
    if (rows.length !== 15 || new Set(rows.map(row => row.ActivityStartDate)).size !== 15) throw Error("Lake reference dates are incomplete: " + site);
  }
  const candidates = two.filter(row => dates.includes(row.ActivityStartDate));
  if (candidates.length !== 32) throw Error("Expected original thirty-two date-matched upstream candidates");
  const exclusionEvidence = EXCLUDED.map(choice => {
    const day = csvParse(inputs[choice.day_input]);
    const excluded = candidates.filter(row => row.ActivityIdentifier === choice.chlorophyll_activity_id);
    const selected = candidates.filter(row => row.MonitoringLocationIdentifier === "21SC60WQ_WQX-" + choice.site_id &&
      row.ActivityStartDate === choice.date && row["ActivityStartTime/Time"] === choice.study_time);
    const routine = day.filter(row => row.ActivityIdentifier === choice.routine_activity_id &&
      row.ProjectIdentifier === "SWS-2023" && row.ActivityStartDate === choice.date &&
      row["ActivityStartTime/Time"] === choice.routine_time);
    if (excluded.length !== 1 || selected.length !== 1 || !routine.length ||
        excluded[0].ResultMeasureValue !== choice.routine_value || selected[0].ResultMeasureValue !== choice.study_value) {
      throw Error("Original activity/time/value evidence does not match " + choice.site_id);
    }
    return {...choice,project_identifier_alone_is_insufficient:true,
      timezone_interpretation:"Chlorophyll labels EST; SWS-2023 labels EDT. Original labels are retained; this association uses the displayed local clock, not a UTC-normalized timestamp.",
      excluded_original_record:recordReference(excluded[0]),retained_original_record:recordReference(selected[0]),
      coincident_routine_activity:{activity_id:choice.routine_activity_id,project_identifier:"SWS-2023",
        date:choice.date,time:choice.routine_time,timezone:routine[0]["ActivityStartTime/TimeZoneCode"],
        original_result_rows:routine.length,characteristics:[...new Set(routine.map(row=>row.CharacteristicName))]}};
  });
  const excludedIds = new Set(EXCLUDED.map(row => row.chlorophyll_activity_id));
  const selected = [...three,...candidates.filter(row => !excludedIds.has(row.ActivityIdentifier))]
    .sort((a,b) => [a.MonitoringLocationIdentifier,a.ActivityStartDate,a["ActivityStartTime/Time"],a.ActivityIdentifier].join("|")
      .localeCompare([b.MonitoringLocationIdentifier,b.ActivityStartDate,b["ActivityStartTime/Time"],b.ActivityIdentifier].join("|")));
  if (new Set(selected.map(row => row.ActivityIdentifier)).size !== 75) throw Error("Selected original activity IDs are not unique");
  const summary = Object.entries(PUBLISHED).map(([site,published]) => {
    const rows = selected.filter(row => row.MonitoringLocationIdentifier === "21SC60WQ_WQX-" + site);
    if (rows.length !== 15 || new Set(rows.map(row => row.ActivityStartDate)).size !== 15) throw Error("Expected one source observation per lake date: " + site);
    if (rows.some(row => row["ResultMeasure/MeasureUnitCode"] !== "ug/L" || row.ResultMeasureValue.trim() === "" ||
      !Number.isFinite(Number(row.ResultMeasureValue)))) throw Error("Original chlorophyll unit or quantity differs");
    const values = rows.map(row => Number(row.ResultMeasureValue));
    const mean = values.reduce((a,b)=>a+b,0) / values.length;
    const sd = Math.sqrt(values.reduce((sum,value)=>sum+(value-mean)**2,0)/(values.length-1));
    const minimum = Math.min(...values), maximum = Math.max(...values);
    return {site_id:site,cohort_n:rows.length,mean,sample_sd:sd,minimum,maximum,units:"ug/L",
      published_mean:published.mean,published_sd:published.sd,published_minimum:published.minimum,
      published_maximum:published.maximum,published_n_reported:published.n_reported,
      rounded_mean_sd_match:Math.abs(mean-published.mean)<=0.05000001 && Math.abs(sd-published.sd)<=0.05000001,
      rounded_range_match:Math.abs(minimum-published.minimum)<=0.05000001 && Math.abs(maximum-published.maximum)<=0.05000001};
  });
  const result = {schema:"upstate.eighteenmile-chlorophyll-cohort/v1",operation_id:"ECO-INTEGRATE-ASTRA13-20261012",
    cohort_basis:"Reconciled original WQP study-date cohort; separate same-date SWS-2023 routine visits identified by publisher-displayed local date/time",
    dates,source_rows:{three_lake_results:csvParse(inputs.three).length,three_lake_chlorophyll:three.length,
      upstream_chlorophyll:two.length,upstream_date_candidates:candidates.length,excluded_same_date_routine:exclusionEvidence.length,selected:selected.length},
    statistic_basis:"Arithmetic mean and sample standard deviation (n-1) of original measured concentrations",
    parameter:CHLOROPHYLL,units:"ug/L",selected_original_records_modified:false,
    publisher_table:{url:"https://des.sc.gov/sites/des/files/Documents/BOW/WaterQuality/2023LakeProgramFinalReport.pdf",
      table:7,printed_page:14,pdf_viewer_page:21,printed_n_sum:53,methods_samples:75,
      interpretation:"The reconciled measured cohort has fifteen observations at each site and reproduces the published means and sample deviations. Original printed n=4 fields for SV-374 and SV-840 are retained separately."},
    exclusion_evidence:exclusionEvidence,summary};
  return {selected,summary,result,
    files:{"study_chlorophyll_cohort.csv":csvString(selected,Object.keys(three[0])),
      "cohort_summary.csv":csvString(summary,Object.keys(summary[0])),
      "cohort_reconciliation.json":JSON.stringify(result,null,2)+"\n"}};
}

export { csvParse, csvString, reconcile };

