"""Editable GIS inside the original Operator task, upload and download lifecycle."""
from __future__ import annotations
import re
import urllib.parse
import zipfile
from model import gis_project as gis
from model import gis_workspace

ACTIONS = frozenset({'gis.project.export', 'gis.project.receive', 'gis.project.adopt-sources'})
# Received HTML has an opaque sandbox origin: it cannot read the operator session.
VIEW_POLICY = ("sandbox allow-scripts allow-downloads; default-src 'none'; "
               "script-src 'unsafe-inline'; style-src 'unsafe-inline'; img-src data:; "
               "connect-src 'none'; object-src 'none'; base-uri 'none'; form-action 'none'; "
               "frame-ancestors 'self'")


def identity(value):
    if not isinstance(value, str) or not re.fullmatch(r'[0-9a-f]{64}', value):
        raise ValueError('Choose a retained GIS project identity')
    return value


class GISProjects:
    """Stateless adapter; mutations are queued by Operator.submit and its workspace gate."""
    def __init__(self, operator):
        self.operator = operator

    def _record(self, workspace, kind, key):
        ws = self.operator.ws(workspace)
        identity(key)
        if kind not in {'export', 'received'}:
            raise ValueError('Choose an exported or received GIS project')
        parent = ws.root / ('gis-exports' if kind == 'export' else 'gis-received') / key
        record = gis.load(parent / ('export.json' if kind == 'export' else 'receipt.json'))
        if record['id'] != key or record['project_id'] != ws.project['id']:
            raise ValueError('The GIS record belongs to another original project')
        if record['state'] != 'complete':
            raise ValueError('Complete this GIS operation before opening its files')
        return ws, parent, record

    def member(self, workspace, kind, key, name):
        ws, parent, record = self._record(workspace, kind, key)
        root = parent / 'project'
        gis.member(name)
        inv = gis.load(root / 'inventory.json')
        if gis.fingerprint(inv['files']) != inv['fingerprint']:
            raise ValueError('GIS inventory changed')
        # A local desktop edit must be sealed into a new edition and received explicitly.
        if inv['fingerprint'] != record['result']['fingerprint']:
            raise ValueError('This GIS working edition changed; receive its new sealed archive')
        expected = next((item for item in inv['files'] if item['path'] == name), None)
        if expected is None:
            if name != 'inventory.json':
                raise ValueError('This file is not a member of the retained GIS project')
            expected = gis.record(root, root / name)
        path = gis.checked(root, expected)
        ticket = self.operator._ticket(workspace, path, expected, name)
        # Apply the opaque-origin policy to ALL members, including supplied SVG/HTML.
        return ticket, VIEW_POLICY

    def describe(self, workspace, kind, key):
        ws, parent, record = self._record(workspace, kind, key)
        archive = gis.local(ws.root, record['archive']['path'])
        if archive.stat().st_size != record['archive']['bytes']:
            raise ValueError('The retained GIS ZIP changed')
        ticket = self.operator._ticket(workspace, archive, record['archive'],
                                       'Complete editable GIS project ZIP')
        prefix = '/api/file/gis-project/' + '/'.join(
            urllib.parse.quote(str(part), safe='') for part in (workspace, kind, key)) + '/'
        return {**record, 'kind': kind, 'viewer_url': prefix + 'OPEN_GIS.html',
                'qgis_url': prefix + 'project.qgz?download=1', 'archive_download': ticket,
                'layers': record['result']['layers'], 'bytes': record['result']['bytes']}

    def catalogue(self, workspace):
        ws = self.operator.ws(workspace)
        result = gis_workspace.catalogue(ws)
        result['exports'] = [self.describe(workspace, 'export', r['id']) for r in result['exports']]
        result['received'] = [self.describe(workspace, 'received', gis.load(p)['id'])
                              for p in sorted((ws.root / 'gis-received').glob('*/receipt.json'))]
        result['adoptions'] = [gis.load(p) for p in sorted((ws.root / 'gis-source-adoptions').glob('*/adoption.json'))]
        for record in result['received']:
            project = gis.load(ws.root / 'gis-received' / record['id'] / 'project' / 'project.json')
            record['layer_choices'] = [{'id': layer['id'], 'title': layer['title'], 'kind': layer['data']['kind'], 'units': layer['data']['units']} for layer in project['layers']]
        result['grids'] = [{k: row.get(k) for k in ('id', 'state', 'spec', 'grid')}
                           for row in (gis.load(p) for p in sorted((ws.root / 'grids').glob('*/grid.json')))]
        result['comparisons'] = [{k: row.get(k) for k in ('id', 'baseline_run_id', 'direction')}
                                 for row in (gis.load(p) for p in sorted((ws.root / 'comparisons').glob('*/comparison.json')))]
        # Human titles come from retained scenario records, not inferred run hashes.
        for row in result['runs']:
            scenario = ws._get('scenarios', row['selection']['scenario_id'])
            row['title'] = scenario['title']
        return {**result, 'workspace_key': workspace}

    def invoke(self, task):
        ws = self.operator.ws(task['workspace'])
        if task['action'] == 'gis.project.export':
            return gis_workspace.export(ws, task['payload'])
        if task['action'] == 'gis.project.adopt-sources':
            return gis_workspace.adopt_sources(ws, task['payload'])
        if task['action'] != 'gis.project.receive':
            raise ValueError('Unsupported GIS operation')
        upload = self.operator.upload(task['payload']['upload_id'])
        return gis_workspace.receive(ws, upload['path'], source_upload_id=upload['id'])

    def decorate_task(self, task):
        if task['action'] in {'gis.project.export', 'gis.project.receive'} and task['state'] == 'complete':
            kind = 'export' if task['action'] == 'gis.project.export' else 'received'
            result = self.describe(task['workspace'], kind, task['result']['id'])
            viewer, _ = self.member(task['workspace'], kind, task['result']['id'], 'OPEN_GIS.html')
            task = {**task, 'result': result,
                    '_downloads': [result['archive_download'],
                        {**viewer, 'url': result['viewer_url'],
                         'label': 'Open GIS layer view and operating guide'}]}
        return task


# Current upstate.operator-extension/v1 host callbacks. Both integration routes
# invoke this same feature implementation through the original queue.
def invoke(operator, workspace_key, action, payload):
    return GISProjects(operator).invoke({'workspace': workspace_key, 'action': action, 'payload': payload})


def read(operator, workspace_key, operation, payload):
    adapter = GISProjects(operator)
    if operation == 'catalogue':
        return adapter.catalogue(workspace_key)
    raise ValueError('Choose the GIS catalogue operation')


def overview(operator, workspace_key):
    ws = operator.ws(workspace_key)
    rows = []
    for kind, pattern in [('export', 'gis-exports/*/export.json'), ('received', 'gis-received/*/receipt.json')]:
        for path in sorted(ws.root.glob(pattern)):
            record = gis.load(path)
            rows.append({'id': record['id'], 'title': record['title'], 'kind': kind,
                         'state': record['state'], 'edition_id': record['result']['edition_id']})
    return rows


def decorate_task(operator, task):
    return GISProjects(operator).decorate_task(task)


def verify_workspace(workspace):
    rows = []
    for pattern in ('gis-exports/*/export.json', 'gis-received/*/receipt.json'):
        for path in sorted(workspace.root.glob(pattern)):
            record = gis.load(path)
            result = gis.verify(path.parent / 'project')
            if record['result']['fingerprint'] != result['fingerprint']:
                raise ValueError('GIS project differs from its recorded receiving/export edition')
            gis.checked(workspace.root, record['archive'])
            rows.append(result)
    for path in sorted((workspace.root / 'gis-source-adoptions').glob('*/adoption.json')):
        adoption = gis.load(path)
        workspace._get('sources', adoption['source_collection_id'])
        gis.checked(workspace.root, adoption['manifest'])
    return {'schema': 'upstate.gis-workspace-readback/v1', 'projects': rows}


def member(operator, workspace_key, kind, project_id, member_path):
    """Bind the existing inventory-checked member to the shared file transport."""
    return GISProjects(operator).member(workspace_key, kind, project_id, member_path)

"""Parcel source workflow bound to the original authenticated operator."""
from __future__ import annotations

from pathlib import Path, PurePosixPath

from model import parcel_source_desk as model
from model.common import digest, identifier, relative_file

ACTIONS = frozenset({"parcel.source.receive", "parcel.source.prepare"})
READS = frozenset({"catalog", "directories", "capture", "edition", "rows", "study-selection"})


class ParcelSourceDesk:
    def __init__(self, operator, fault, source_roots=()):
        self.operator, self.Fault = operator, fault
        roots = [Path(value) for value in source_roots]
        roots.extend(Path(row["path"]).parent for row in operator.registered.values())
        self.roots = {}
        for root in roots:
            path = root.expanduser().resolve(strict=True)
            if not path.is_dir():
                raise ValueError("Each registered parcel source root must be a directory")
            self.roots[digest({"source_root": str(path)})] = path

    def _error(self, message, code="PARCEL_SOURCE_REQUEST", status=422):
        raise self.Fault(code, message, status)

    @staticmethod
    def _one(value, field, default=None):
        value = value.get(field, default)
        if isinstance(value, list):
            if len(value) != 1:
                raise ValueError("Choose one " + field.replace("_", " "))
            value = value[0]
        return value

    def _directory(self, value):
        root_id = self._one(value, "root_id")
        root = self.roots.get(root_id)
        if root is None:
            self._error("Choose a source directory registered by this operator.", "PARCEL_SOURCE_ROOT", 404)
        name = self._one(value, "path", "")
        if not isinstance(name, str) or "\\" in name or "\0" in name:
            self._error("Choose a canonical relative source directory.")
        if name:
            member = PurePosixPath(name)
            if (member.is_absolute() or member.as_posix() != name
                    or any(part in {"", ".", ".."} for part in name.split("/"))):
                self._error("The source directory must stay within its registered root.")
            selected = (root / member).resolve(strict=True)
        else:
            selected = root
        if not selected.is_relative_to(root) or not selected.is_dir():
            self._error("Choose an existing directory within the registered source root.")
        return selected, {"root_id": root_id, "path": name}

    def _browse(self, value):
        path, locator = self._directory(value)
        offset = self._one(value, "offset", 0)
        if isinstance(offset, str) and offset.isdecimal():
            offset = int(offset)
        if isinstance(offset, bool) or not isinstance(offset, int) or offset < 0:
            self._error("Choose a nonnegative directory page.")
        root = self.roots[locator["root_id"]]
        members = []
        for child in path.iterdir():
            if child.name.startswith("."):
                continue
            try:
                selected = child.resolve(strict=True)
                if not selected.is_relative_to(root) or not selected.is_dir():
                    continue
            except OSError:
                continue
            members.append({
                "name": child.name, "path": child.relative_to(root).as_posix(),
                "has_plan": (selected / "parcel-plan.json").is_file(),
                "has_progress": (selected / "capture-progress.json").is_file(),
                "has_inventory": (selected / "parcel-inventory.json").is_file(),
            })
        members.sort(key=lambda row: (row["name"].casefold(), row["name"]))
        parent = PurePosixPath(locator["path"]).parent.as_posix() if locator["path"] else ""
        return {
            "locator": locator, "parent": "" if parent == "." else parent,
            "has_plan": (path / "parcel-plan.json").is_file(),
            "directories": members[offset:offset + 100], "offset": offset,
            "total": len(members),
            "next_offset": offset + 100 if offset + 100 < len(members) else None,
        }

    def _edition(self, workspace, edition_id):
        ws = self.operator.ws(workspace)
        value = model.get(ws, edition_id)
        result = dict(value)
        result["_downloads"] = []
        labels = {
            "gpkg": "Parcel, cadastral, county and gap GeoPackage",
            "parcel_csv": "Complete parcel inventory CSV",
            "context_csv": "Complete cadastral context CSV",
            "county_coverage_csv": "County source coverage CSV",
            "county_sources_csv": "Original county source editions CSV",
            "excluded_records_csv": "Excluded original records CSV",
            "geometry_corrections": "Original geometry corrections",
            "methods": "Parcel methods and units",
            "import_manifest": "Original source import manifest",
            "report": "Printable parcel source report",
        }
        for name, label in labels.items():
            item = value["files"].get(name)
            if not item:
                continue
            path = relative_file(ws.root, item["path"])
            result["_downloads"].append(self.operator._ticket(workspace, path, item, label))
        return result

    def read(self, workspace_key, operation, payload=None):
        self.operator.ws(workspace_key)
        value = payload or {}
        if not isinstance(value, dict):
            self._error("Choose a parcel source selection.")
        ws = self.operator.ws(workspace_key)
        if operation == "catalog":
            data = model.overview(ws)
            data["roots"] = [{"id": key, "label": str(path)} for key, path in self.roots.items()]
            data["workspace_key"] = workspace_key
            return data
        if operation == "directories":
            return self._browse(value)
        if operation == "capture":
            path, locator = self._directory(value)
            return {**model.preview(path), "locator": locator}
        if operation == "edition":
            return self._edition(workspace_key, self._one(value, "edition_id", self._one(value, "id")))
        if operation == "rows":
            return model.rows(
                ws, self._one(value, "edition_id"), table=self._one(value, "table", "parcels"),
                county=self._one(value, "county", ""), query=self._one(value, "query", ""),
                offset=self._one(value, "offset", 0), limit=self._one(value, "limit", 100),
            )
        if operation == "study-selection":
            spec = value.get("spec") or {}
            if not isinstance(spec, dict):
                self._error("Supply the intended conservation inventory settings.")
            return model.study_selection(ws, self._one(value, "edition_id"), spec)
        self._error("Unknown parcel source operation.", "PARCEL_SOURCE_ROUTE", 404)

    def invoke(self, task):
        ws = self.operator.ws(task["workspace"])
        value = task.get("payload") or {}
        if not isinstance(value, dict):
            self._error("Supply the selected original parcel capture.")
        if task["action"] == "parcel.source.prepare":
            selection = model._expected(value.get("selection"))
            retained = ws.root / "parcel-source-inputs" / digest(selection) / "desk-input-snapshot.json"
            if retained.is_file():
                directory = None
                locator = {"root_id": value.get("root_id"), "path": value.get("path", "")}
            else:
                directory, locator = self._directory(value)
            return model.operate(
                ws, directory, value.get("selection"), title=value.get("title"),
                operation_id=task["id"], locator=locator,
            )
        if task["action"] == "parcel.source.receive":
            directory, locator = self._directory(value)
            from source_tools import reporting_parcels as native
            current = model.preview(directory)
            if identifier(value.get("plan_sha256")) != current["plan_sha256"]:
                self._error("The parcel acquisition plan changed. Refresh and select its current retained edition.",
                            "PARCEL_PLAN_CHANGED", 409)
            requested = value.get("providers") or None
            if requested is not None and (not isinstance(requested, list)
                    or any(not isinstance(item, str) for item in requested)):
                self._error("Choose the original county provider identifiers.")
            retry = value.get("retry_failed", False)
            if not isinstance(retry, bool):
                self._error("Choose whether to retry retained provider failures.")
            outcome = native.receive(directory, providers=requested, retry_failed=retry)
            return {"schema": model.SCHEMA, "kind": "parcel-source-acquisition",
                    "locator": locator, "outcome": outcome, "capture": model.preview(directory)}
        self._error("Unknown parcel source action.", "PARCEL_SOURCE_ACTION", 404)

    def state(self, workspace_key):
        return model.overview(self.operator.ws(workspace_key))

    def decorate_task(self, task):
        if task.get("action") not in ACTIONS:
            return task
        result = task.get("result")
        if not isinstance(result, dict):
            return task
        value = dict(task)
        if task["action"] == "parcel.source.prepare" and result.get("id"):
            edition = self._edition(task["workspace"], result["id"])
            value["_downloads"] = [*value.get("_downloads", []), *edition["_downloads"]]
            value["_parcel_source"] = {
                "edition_id": edition["id"],
                "source_collection_id": edition["source_collection_id"],
                "parcel_count": edition["native_inventory"]["parcel_count"],
                "capture_state": edition["native_inventory"]["capture_state"],
            }
        else:
            capture = result.get("capture") or {}
            value["_parcel_source"] = {
                "capture_state": capture.get("state"),
                "complete_counties": capture.get("complete_counties"),
                "required_counties": capture.get("required_counties"),
                "locator": result.get("locator"),
            }
        return value

"""Receiving-water operations through the original operator task and file APIs."""
from __future__ import annotations
from collections import OrderedDict
from copy import deepcopy
from threading import RLock
from model.common import atomic_json, describe_file, held, identifier, now, read_json
from model import receiving_waters

ACTIONS = frozenset({
    "receiving.water.plan", "receiving.water.profile", "receiving.water.analyze",
    "receiving.water.catalog",
})
READS = frozenset({"catalog", "plan", "analysis", "designation-catalog"})


class ReceivingWaterActions:
    def __init__(self, operator, fault):
        self.operator = operator
        self.Fault = fault
        self._summary_cache = OrderedDict()
        self._summary_lock = RLock()

    @staticmethod
    def _plan_summary(row):
        return {
            "id": row["id"], "title": row["title"], "state": row["state"],
            "created_at": row["created_at"], "receptor_count": len(row["receptors"]),
            "families": sorted({item["family"] for item in row["receptors"]}),
            "source_count": len({
                (item["source_collection_id"], item["source_id"], item["body_sha256"])
                for item in row["identity"]["source_identities"]
            }),
        }

    @staticmethod
    def _analysis_summary(row):
        names = (
            "id", "title", "state", "created_at", "completed_at", "plan_id",
            "baseline_run_id", "alternative_run_ids", "quantity_scope", "pollutants",
            "completed_subjects", "total_subjects", "error",
        )
        return {name: row.get(name) for name in names}

    @staticmethod
    def _catalog_summary(row):
        return {name: row.get(name) for name in (
            "id", "title", "state", "created_at", "as_of", "record_count",
            "selected_count", "prepared_plan_ids", "error",
        )}

    @staticmethod
    def _manifest_identity(path):
        stat = path.stat()
        return (stat.st_dev, stat.st_ino, stat.st_mtime_ns, stat.st_ctime_ns, stat.st_size)

    def snapshot(self, workspace):
        ws = self.operator.ws(workspace)
        workspace_key = (str(ws.root), ws.project["id"])
        groups = (
            ("receiving_water_catalogs", "receiving-water-catalogs", "operator-catalog.json",
             lambda path: read_json(path), self._catalog_summary),
            ("receiving_water_plans", "receiving-water-plans", "plan.json",
             lambda path: receiving_waters.inspect_plan(ws, path.parent.name, verify=False),
             self._plan_summary),
            ("receiving_water_analyses", "receiving-water-analyses", "analysis.json",
             lambda path: receiving_waters.inspect(ws, path.parent.name, verify=False),
             self._analysis_summary),
        )
        # The operator serves concurrent browser polls. Retain only compact
        # summaries, with a fixed maximum of 16 workspaces / 1024 manifests each.
        # Every poll still enumerates and stats real manifests; immutable paths
        # alone never authorize reusing an earlier summary.
        with self._summary_lock:
            cache = self._summary_cache.setdefault(workspace_key, OrderedDict())
            self._summary_cache.move_to_end(workspace_key)
            while len(self._summary_cache) > 16:
                self._summary_cache.popitem(last=False)
            result, present = {}, set()
            for name, directory, filename, loader, summarize in groups:
                rows = []
                for path in sorted((ws.root / directory).glob("*/" + filename)):
                    manifest_key = str(path.relative_to(ws.root))
                    present.add(manifest_key)
                    before = self._manifest_identity(path)
                    retained = cache.get(manifest_key)
                    if retained is not None and retained[0] == before:
                        row = retained[1]
                        cache.move_to_end(manifest_key)
                    else:
                        row = summarize(loader(path))
                        after = self._manifest_identity(path)
                        if before == after:
                            cache[manifest_key] = (after, row)
                            cache.move_to_end(manifest_key)
                            while len(cache) > 1024:
                                cache.popitem(last=False)
                        else:
                            # An atomic replacement during this read is a valid
                            # snapshot, but it must be read afresh on the next poll.
                            cache.pop(manifest_key, None)
                    rows.append(deepcopy(row))
                result[name] = rows
            for key in list(cache):
                if key not in present:
                    del cache[key]
            while len(cache) > 1024:
                cache.popitem(last=False)
            return result

    def read(self, workspace, operation, value=None):
        ws = self.operator.ws(workspace)
        value = value or {}
        if operation == "catalog":
            overview = ws.overview()
            try:
                from source_tools.receiving_water_catalog import PROFILES, FIELD_ALIASES, CLASS_CODES
            except ModuleNotFoundError as error:
                if error.name not in ("source_tools", "source_tools.receiving_water_catalog"):
                    raise
                compiler_profiles = []
            else:
                compiler_profiles = [
                    {"id": key, **row,
                     "required_fields": ["classification"] if row["kind"] == "classified_water" else [],
                     "field_aliases": FIELD_ALIASES, "class_codes": list(CLASS_CODES)}
                    for key, row in PROFILES.items()
                ]
            return {
                "workspace_key": workspace, "project": ws.project, **self.snapshot(workspace),
                "sources": [
                    {"id": row["id"], "title": row["title"], "captured_at": row.get("captured_at"),
                     "entries": [
                         {key: entry.get(key) for key in
                          ("id", "title", "kind", "role", "vintage", "uri", "layer", "metadata")}
                         for entry in row["entries"] if entry["kind"] == "vector"
                     ]}
                    for row in overview["sources"]
                ],
                "grids": [
                    {"id": row["id"], "state": row["state"], "spec": row["spec"],
                     "grid": row["grid"]} for row in overview["grids"]
                ],
                "runs": [
                    {"id": row["id"], "state": row["state"], "selection": row["selection"]}
                    for row in overview["runs"]
                ],
                "profiles": overview["profiles"], "scenarios": overview["scenarios"],
                "families": list(receiving_waters.FAMILIES),
                "relationships": ["upstream_huc", "source_area", "geometric_context"],
                "quantity_scopes": ["reporting", "model_domain"],
                "compiler_profiles": compiler_profiles,
            }
        if operation == "designation-catalog":
            key = identifier(value.get("catalog_id"))
            directory = ws.root / "receiving-water-catalogs" / key
            result = read_json(directory / "operator-catalog.json")
            if result.get("id") != key:
                raise ValueError("The retained receiving-water catalog identity changed")
            catalog = read_json(directory / "receiving-water-catalog.json")
            result["catalog"] = {
                **catalog,
                "records": [
                    {name: field for name, field in row.items() if name != "geometry"}
                    for row in catalog["records"]
                ],
            }
            filename = "operator-catalog.json"
        elif operation == "plan":
            key = identifier(value.get("plan_id"))
            result = receiving_waters.inspect_plan(ws, key, verify=False)
            directory = ws.root / "receiving-water-plans" / key
            filename = "plan.json"
        elif operation == "analysis":
            key = identifier(value.get("analysis_id"))
            result = receiving_waters.inspect(ws, key, verify=False)
            directory = ws.root / "receiving-water-analyses" / key
            filename = "analysis.json"
        else:
            raise self.Fault("RECEIVING_WATER_READ", "Choose a receiving-water view.", 404)
        downloads = self.operator._files(workspace, result, directory)
        downloads.append(self.operator._ticket(
            workspace, directory / filename, describe_file(directory, directory / filename),
            "Complete receiving-water " + operation,
        ))
        return {**result, "_downloads": downloads}

    def invoke(self, task):
        ws = self.operator.ws(task["workspace"])
        value = task["payload"]
        action = task["action"]
        if action == "receiving.water.catalog":
            from source_tools.receiving_water_catalog import compile_catalog, write_catalog
            selection = value.get("selection", value)
            vintage = value.get("prepare_vintage", "effective")
            if vintage not in ("effective", "proposed", None):
                raise ValueError("Choose effective or proposed designation vintage")
            compiled = compile_catalog(ws, selection)
            catalog = compiled["catalog"]
            key = identifier(catalog["id"])
            directory = ws.root / "receiving-water-catalogs" / key
            record_path = directory / "operator-catalog.json"
            with held(ws.root / ".workspace.lock"):
                previous = read_json(record_path) if record_path.is_file() else {}
                if previous and previous.get("id") != key:
                    raise ValueError("The retained source catalog belongs to another selection")
                write_catalog(compiled, directory)
                result = {
                    "id": key, "title": catalog.get("title") or selection.get("title") or "Receiving-water source catalog",
                    "state": "compiled", "created_at": previous.get("created_at") or now(), "as_of": selection.get("as_of"),
                    "record_count": len(catalog["records"]),
                    "selected_count": sum(bool(row.get("selected")) for row in catalog["records"]),
                    "prepared_plan_ids": dict(previous.get("prepared_plan_ids", {})), "files": {},
                }
                for name in (
                    "receiving-water-catalog.json", "receiving-water-records.geojson",
                    "prepare-effective.json", "prepare-proposed.json",
                    "receiving-water-index.csv", "catalog-files.json",
                ):
                    if (directory / name).is_file():
                        result["files"][name] = describe_file(directory, directory / name)
                atomic_json(record_path, result)
            try:
                if vintage and compiled["plans"][vintage].get("receptors"):
                    plan = receiving_waters.prepare(ws, compiled["plans"][vintage])
                    result["prepared_plan_ids"][vintage] = plan["id"]
                result["state"] = "complete"
                with held(ws.root / ".workspace.lock"):
                    atomic_json(record_path, result)
                return self._catalog_summary(result)
            except BaseException as error:
                result.update(state="failed", error={"type": type(error).__name__, "message": str(error)})
                with held(ws.root / ".workspace.lock"):
                    atomic_json(record_path, result)
                raise
        if action == "receiving.water.plan":
            result = receiving_waters.prepare(ws, value.get("selection", value))
            return self._plan_summary(result)
        if action == "receiving.water.profile":
            result = receiving_waters.prepare_receptor_spec(
                ws, value["receptor_spec"], grid_id=value.get("grid_id"),
            )
            return self._plan_summary(result)
        if action == "receiving.water.analyze":
            result = receiving_waters.analyze(ws, value.get("selection", value))
            return self._analysis_summary(result)
        raise self.Fault("RECEIVING_WATER_ACTION", "Choose a receiving-water operation.")

    def decorate_task(self, task):
        if task.get("action") not in ACTIONS or task.get("state") != "complete":
            return task
        result = task["result"]
        kind = ("analysis" if task["action"] == "receiving.water.analyze"
                else "designation-catalog" if task["action"] == "receiving.water.catalog" else "plan")
        field = "catalog_id" if kind == "designation-catalog" else kind + "_id"
        original = self.read(task["workspace"], kind, {field: result["id"]})
        return {
            **task, "_receiving_water": {"kind": kind, "id": result["id"]},
            "_downloads": original["_downloads"],
        }

