.calibration-badge{display:inline-block;border:1px solid #aaa;border-radius:3px;background:#f4f4f4;color:#222;padding:3px 7px;font-size:12px;line-height:1.4}
.calibration-card-value{display:block;font-size:23px;font-weight:600;line-height:1.3;overflow-wrap:anywhere;margin:8px 0}
.calibration-reading p{max-width:90ch}
.calibration-tabs{display:flex;gap:0;flex-wrap:wrap;border-bottom:1px solid #bbb;background:#f4f4f4}
.calibration-tabs button{background:transparent;color:#333;border:0;border-radius:0;border-bottom:3px solid transparent;padding:12px 14px;white-space:nowrap}
.calibration-tabs button[aria-selected=true]{background:#fff;border-bottom-color:#333;font-weight:650}
.calibration-tabs small{margin-left:4px;color:#666}
.calibration-table-controls{padding:16px 20px;display:flex;justify-content:space-between;border-bottom:1px solid #ddd}
