.calibration-sort{border:0!important;background:transparent!important;color:inherit!important;text-align:left;padding:0!important;min-height:0!important;border-radius:0!important;font:inherit!important;font-weight:600!important}
.calibration-pagination{padding:14px 20px;display:flex;justify-content:space-between;gap:15px;align-items:center;border-top:1px solid #ddd;font-size:13px}
.calibration-pagination>div{display:flex;gap:8px}
.calibration-pagination button:disabled{opacity:.45;cursor:default}
.calibration-empty{padding:20px;margin:0;color:#555}
