.water-heading h1{margin:.2rem 0 .6rem;font-size:1.8rem;line-height:1.25}
.water-heading p{max-width:80ch;margin:.35rem 0;color:#555}
.water-actions,.water-row-actions{display:flex;align-items:center;gap:.5rem;flex-wrap:wrap}
.water-actions button,.water-workbench button{min-height:36px;border:1px solid #aaa;background:#fff;color:#222;border-radius:3px;padding:.45rem .7rem;font:inherit;cursor:pointer}
.water-actions button:hover,.water-workbench button:hover{background:#f1f1f1}
.water-actions button.primary,.water-workbench button.primary{background:#333;color:#fff;border-color:#333}
.water-actions button:disabled,.water-workbench button:disabled{cursor:default;color:#777;background:#f5f5f5;border-color:#ddd}
.water-workbench button:focus-visible,.water-actions button:focus-visible,.water-workbench input:focus-visible,.water-workbench select:focus-visible{outline:2px solid #222;outline-offset:3px}
.water-summary{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1px;border:1px solid #ccc;background:#ccc;margin:0 0 1.5rem}
.water-summary>div{background:#fafafa;padding:1rem;display:flex;align-items:baseline;gap:.7rem}
.water-summary strong{font-size:1.65rem;font-variant-numeric:tabular-nums}
.water-summary span{color:#555}
.water-section{border:1px solid #ccc;background:#fff;margin:0 0 1.5rem;border-radius:3px;overflow:hidden}
.water-section>header,.water-section>.water-filters,.water-section>.water-note,.water-section>.water-progress,.water-section>.water-result-count,.water-section>.water-empty,.water-section>.water-loading,.water-section>details,.water-section>.water-error{padding:1rem 1.15rem;margin:0}
.water-section>header{border-bottom:1px solid #ddd;background:#fafafa}
.water-section h2{font-size:1.2rem;line-height:1.35;margin:0 0 .35rem}
.water-section header p{margin:.3rem 0;color:#555}
.water-section details{border-top:1px solid #ddd}
.water-section summary{font-weight:600;cursor:pointer;padding:.15rem 0}
.water-section details[open]>summary{margin-bottom:.9rem}
.water-table-scroll{width:100%;overflow-x:auto;overscroll-behavior-x:contain}
.water-table-scroll table{width:100%;border-collapse:collapse;font-size:.92rem}
.water-table-scroll th,.water-table-scroll td{padding:.7rem .85rem;border-bottom:1px solid #e2e2e2;text-align:left;vertical-align:top;white-space:normal}
.water-table-scroll th{background:#f5f5f5;font-weight:600}
.water-table-scroll td small{display:block;color:#666;margin-top:.25rem}
.water-table-scroll tbody tr:last-child td,.water-table-scroll tbody tr:last-child th{border-bottom:0}
.water-table-scroll .water-number{text-align:right;white-space:nowrap;font-variant-numeric:tabular-nums}
.water-table-scroll .water-row-actions{min-width:150px}
.water-status{display:inline-block;padding:.2rem .45rem;font-size:.83rem;border:1px solid #aaa;border-radius:3px;background:#f5f5f5;white-space:nowrap}
.water-filters{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:.8rem;align-items:end}
.water-filters label{display:flex;flex-direction:column;gap:.35rem;font-size:.9rem}
.water-filters input,.water-filters select{width:100%;min-height:38px;border:1px solid #aaa;border-radius:3px;padding:.45rem;background:#fff;color:inherit;font:inherit}
.water-note,.water-empty,.water-loading,.water-progress{line-height:1.55;color:#555}
.water-empty{padding:1rem}
.water-error{border-left:4px solid #555;background:#f5f5f5;color:#222;padding:.8rem}
.water-result-count{padding:.8rem 1.15rem;margin:0;color:#666;font-size:.85rem}
.water-definition{display:grid;gap:.65rem}
.water-definition h3{font-size:1rem;margin:.5rem 0}
.water-receptor-row,.water-catalog-source{border:1px solid #aaa;border-radius:3px;margin:1rem 0;padding:1rem}
.water-receptor-row legend,.water-catalog-source legend{padding:0 .4rem;font-weight:600}
.water-receptor-row .water-actions,.water-catalog-source .water-actions{margin-top:.8rem}
.water-check{display:flex;gap:.55rem;align-items:flex-start;margin:.55rem 0}
.water-check input{width:auto;margin:.2rem 0 0}
#water-result-table>.water-note{padding:.7rem 1.15rem}
#water-catalog-table>.water-section-heading{padding:.6rem 1.15rem}
#water-selected{scroll-margin-top:1rem}
@media(max-width:700px){
  .water-heading h1{font-size:1.5rem}
  .water-heading .water-actions{width:100%;display:grid;grid-template-columns:1fr 1fr}
  .water-summary{grid-template-columns:1fr}
  .water-summary>div{padding:.65rem .9rem}
  .water-summary strong{font-size:1.35rem}
  .water-filters{grid-template-columns:1fr 1fr}
  .water-table-scroll table{min-width:650px}
  .water-section>header{padding:.8rem}
  .water-receptor-row,.water-catalog-source{padding:.65rem}
}
@media(max-width:420px){
  .water-heading .water-actions,.water-filters{grid-template-columns:1fr}
}

/** Regional soil desk using the existing source workbench controls and task queue. */
import {createSourceWorkbench} from './source_workbench.mjs';

export function createRegionalSoilDesk(host) {
  return createSourceWorkbench(host, {
    namespace:'regional-soil',
    storageKey:'upstate-regional-soil-v1',
    prepareAction:'regional-soil.prepare',
    composeAction:'regional-soil.compose',
    title:'Regional soil',
    description:'Capture the original 217-HUC soil domain, continue retained acquisition, then prepare K and coverage on the numeric 30 m land-cover grid. Completed sources stay with this study.'
  });
}

