#!/usr/bin/env node
import {readFile,writeFile,mkdir,rename} from 'node:fs/promises';
import {createHash,randomUUID} from 'node:crypto';
import {dirname,resolve,join} from 'node:path';
import {fileURLToPath} from 'node:url';
import {parseCsv,assessObservedContext,contextCsv,renderContextMarkdown} from './observed_context.mjs';

const application=resolve(process.argv[2]||join(dirname(fileURLToPath(import.meta.url)),'..'));
const output=resolve(process.argv[3]||join(application,'observations/calibration_context_20261013'));
const paths={
  annual:'observations/observed_hydrology_20261013/derived/calendar_year_flow.csv',
  daily:'observations/observed_hydrology_20261013/derived/daily_flow.csv',
  dates:'observations/eighteenmile_2023/wqp/study_flow_dates.csv',
};
const input={},sources=[];
for(const [role,path]of Object.entries(paths)){
  const bytes=await readFile(join(application,path));
  sources.push({role,path,bytes:bytes.length,sha256:createHash('sha256').update(bytes).digest('hex')});
  input[role]=parseCsv(bytes.toString('utf8'));
}
const result={...assessObservedContext(input),input_sources:sources};
const files={
  'assessment.json':JSON.stringify(result,null,2)+'\n',
  'station_year_context.csv':contextCsv(result.station_context),
  'README.md':renderContextMarkdown(result),
};
await mkdir(output,{recursive:true});
for(const [name,text]of Object.entries(files)){
  const destination=join(output,name),temporary=join(output,'.'+name+'.'+randomUUID()+'.tmp');
  await writeFile(temporary,text,{encoding:'utf8',flag:'wx'});
  await rename(temporary,destination);
}
process.stdout.write(JSON.stringify({output,files:Object.keys(files),gauges:result.station_context.length,study_dates:result.sampling_context.sampled_unique_dates})+'\n');

// Reproduce the retained original SCDES point/footprint relationship using Node.js standard libraries.

function assert(condition, message) { if (!condition) throw new Error(message); }
function number(value, label) {
  assert(typeof value === 'number' && Number.isFinite(value), 'Nonfinite coordinate: ' + label);
  return value;
}
function round(value) { return Math.round(value * 1e6) / 1e6; }
function segmentDistance(point, left, right) {
  const dx = right[0] - left[0], dy = right[1] - left[1];
  const denom = dx * dx + dy * dy;
  const ratio = denom === 0 ? 0 : Math.max(0, Math.min(1,
    ((point[0] - left[0]) * dx + (point[1] - left[1]) * dy) / denom));
  return Math.hypot(point[0] - left[0] - ratio * dx, point[1] - left[1] - ratio * dy);
}
function analyseGeometry(rings, point) {
  assert(Array.isArray(rings) && rings.length > 0, 'Polygon has no rings');
  let inside = false, signedTwiceArea = 0, nearest = Infinity, vertices = 0;
  const bounds = [Infinity, Infinity, -Infinity, -Infinity];
  for (const ring of rings) {
    assert(Array.isArray(ring) && ring.length >= 4, 'Invalid polygon ring');
    assert(ring[0][0] === ring[ring.length - 1][0] &&
           ring[0][1] === ring[ring.length - 1][1], 'Unclosed published ring');
    const origin = ring[0];
    vertices += ring.length;
    for (let i = 0; i < ring.length - 1; i++) {
      const a = ring[i], b = ring[i + 1];
      number(a[0], 'x'); number(a[1], 'y'); number(b[0], 'x'); number(b[1], 'y');
      bounds[0] = Math.min(bounds[0], a[0]); bounds[1] = Math.min(bounds[1], a[1]);
      bounds[2] = Math.max(bounds[2], a[0]); bounds[3] = Math.max(bounds[3], a[1]);
      // Translating each ring to its first vertex limits cancellation at UTM magnitudes.
      signedTwiceArea += (a[0] - origin[0]) * (b[1] - origin[1]) -
                         (b[0] - origin[0]) * (a[1] - origin[1]);
      nearest = Math.min(nearest, segmentDistance(point, a, b));
      if ((a[1] > point[1]) !== (b[1] > point[1]) &&
          point[0] < (b[0] - a[0]) * (point[1] - a[1]) / (b[1] - a[1]) + a[0]) {
        inside = !inside;
      }
    }
  }
  // Esri exterior/hole winding determines signed area; even/odd crossing includes all holes.
  return {inside, on_boundary: nearest <= 1e-7, nearest,
          area: Math.abs(signedTwiceArea) / 2, bounds, rings: rings.length, vertices};
}
function assess(polygon, intakes, manifest, identities, calculationIdentity) {
  for (const [label, value] of [['polygon', polygon], ['intakes', intakes]]) {
    assert(value.spatialReference &&
           (value.spatialReference.latestWkid || value.spatialReference.wkid) === 26917,
           label + ' must preserve original EPSG:26917 coordinates');
    assert(Array.isArray(value.features), label + ' has no features');
  }
  assert(polygon.geometryType === 'esriGeometryPolygon', 'Expected original Esri polygon');
  assert(intakes.geometryType === 'esriGeometryPoint', 'Expected original Esri point');
  assert(polygon.features.length === 4, 'Expected exactly four original protection polygons');
  assert(intakes.features.length === 71, 'Expected complete 71-point original response');
  const selectors = [
    {receptor_id:'arjws-swpa-1500', OBJECTID:11, INTAKE:'S04101', BUFFER_FT:1500, intake_object_id:6},
    {receptor_id:'arjws-swpa-200', OBJECTID:12, INTAKE:'S04101', BUFFER_FT:200, intake_object_id:6},
    {receptor_id:'prwd-swpa-1500', OBJECTID:131, INTAKE:'S37109', BUFFER_FT:1500, intake_object_id:50},
    {receptor_id:'prwd-swpa-200', OBJECTID:132, INTAKE:'S37109', BUFFER_FT:200, intake_object_id:50}
  ];
  const rows = selectors.map(selector => {
    const matches = polygon.features.filter(feature => Object.entries(selector)
      .filter(([key]) => ['OBJECTID','INTAKE','BUFFER_FT'].includes(key))
      .every(([key,value]) => feature.attributes[key] === value));
    assert(matches.length === 1, 'Typed polygon selector is not unique: ' + selector.receptor_id);
    const points = intakes.features.filter(feature =>
      feature.attributes.OBJECTID === selector.intake_object_id &&
      feature.attributes.INTAKE === selector.INTAKE);
    assert(points.length === 1, 'Typed intake selector is not unique: ' + selector.receptor_id);
    const feature = matches[0], intake = points[0], attributes = feature.attributes;
    assert(intake.attributes.PWSNO === 'SC' + attributes.SYSTEM, 'Intake/system identity mismatch');
    const point = [number(intake.geometry.x,'intake x'), number(intake.geometry.y,'intake y')];
    const measured = analyseGeometry(feature.geometry.rings, point);
    const sourceArea = number(attributes['Shape.STArea()'], 'published area');
    return {
      receptor_id:selector.receptor_id,
      polygon_selector:{OBJECTID:selector.OBJECTID,INTAKE:selector.INTAKE,BUFFER_FT:selector.BUFFER_FT},
      intake_selector:{OBJECTID:selector.intake_object_id,INTAKE:selector.INTAKE},
      published_polygon_attributes:attributes,
      published_intake_attributes:intake.attributes,
      intake_xy_m:point,
      relationship:measured.on_boundary ? 'boundary' : measured.inside ? 'inside' : 'outside',
      minimum_distance_to_boundary_m:round(measured.nearest),
      minimum_distance_to_footprint_m:measured.inside || measured.on_boundary ? 0 : round(measured.nearest),
      published_area_ha:sourceArea/10000,
      calculated_area_m2:round(measured.area),
      calculated_area_ha:round(measured.area/10000),
      calculated_minus_published_area_m2:round(measured.area-sourceArea),
      bounds_m:measured.bounds.map(round),rings:measured.rings,vertices:measured.vertices
    };
  });
  return {
    schema:'upstate.source-water-geometry-assessment/v1',
    title:'Original SCDES source-water protection footprints and published intake locations',
    captured_at:manifest.captured_at,
    capture_precision:'day; underlying publisher edition and original response time unstated',
    analysis_crs:'EPSG:26917',
    distance_units:'metres',
    sources:manifest.entries.map(entry => ({
      id:entry.id,path:entry.path,uri:entry.uri,vintage:entry.vintage,source_crs:entry.source_crs,
      bytes:entry.bytes,sha256:entry.sha256,git_blob:identities[entry.id].git_blob
    })),
    calculation_source:calculationIdentity,
    method:{
      point_relationship:'Even-odd ray crossing across every original ring; boundary tolerance 1e-7 m.',
      distance:'Minimum Euclidean point-to-segment distance over every exterior and hole ring.',
      area:'Absolute sum of signed ring areas with translated coordinates; original Esri hole winding retained.',
      precision:'Computed distances and areas rounded to 6 decimal places for reproducible serialization.',
      input_treatment:'Original point and polygon coordinates are used directly without reprojection, buffering, simplification or geometry repair.'
    },
    findings:rows,
    interpretation:[
      'ARJWS intake S04101 is within both corresponding published protection footprints.',
      'Pioneer intake S37109 is outside both corresponding published protection footprints; the original geometries retain their distinct locations.',
      'Published protection footprints and intake-based upstream catchments are separate analysis criteria. Use these footprints for protection-area scoring and the original intake point for catchment routing.',
      'The 200-foot and 1500-foot source areas are alternative published scopes. Union overlapping source areas before totals; do not add overlapping footprints as independent area.',
      'A published BUFFER_FT attribute is retained as source metadata, not applied as an additional buffer.'
    ]
  };
}

const sourceDir = process.argv[2];
if (!sourceDir) throw new Error('Usage: node source_tools/assess_public_source_water.mjs SOURCE_DIR [OUTPUT_JSON]');
const [{readFile,writeFile}, {resolve,join}, {createHash}, {fileURLToPath}] = await Promise.all([
  import('node:fs/promises'),import('node:path'),import('node:crypto'),import('node:url')
]);
const base = resolve(sourceDir), digest = value => createHash('sha256').update(value).digest('hex');
const manifestBytes = await readFile(join(base,'sources.public-native.json'));
const manifest = JSON.parse(manifestBytes);
const expected = {
  'scdes-public-surface-intakes-20261012': {bytes:25984,sha256:'29532afb9da03c4d45cf194748618daaace622be455c65881b98bdbe97fc97c2',git_blob:'4299e1afd868f6fa703538ef15f0db7654ae2b46'},
  'scdes-arjws-prwd-swpa-20261012': {bytes:2389556,sha256:'ddac0feb1c704ca5e95336e21961e08beede1f83b6b820423dffa5a63bd8e285',git_blob:'cf9f5bf3a8e2808d2416f8b302d3fc19b7529ada'}
};
const decoded = {};
for (const [id,identity] of Object.entries(expected)) {
  const entries = manifest.entries.filter(entry => entry.id === id);
  assert(entries.length === 1, 'Source manifest identity is not unique: '+id);
  const entry = entries[0], path = resolve(base,entry.path);
  assert(path.startsWith(base + '/'), 'Source path escapes its retained directory');
  assert(entry.bytes === identity.bytes && entry.sha256 === identity.sha256,
         'This assessment requires the preserved 2026-10-12 source edition: '+id);
  const bytes = await readFile(path);
  assert(bytes.length === identity.bytes && digest(bytes) === identity.sha256,
         'Source bytes differ from the retained original: '+id);
  decoded[id] = JSON.parse(bytes);
}
const ownBytes = await readFile(fileURLToPath(import.meta.url));
const result = assess(decoded['scdes-arjws-prwd-swpa-20261012'],
  decoded['scdes-public-surface-intakes-20261012'],manifest,expected,{
    path:'source_tools/assess_public_source_water.mjs',bytes:ownBytes.length,sha256:digest(ownBytes)
  });
const output = JSON.stringify(result,null,2)+'\n';
if (process.argv[3]) await writeFile(process.argv[3],output,{flag:'wx'});
else process.stdout.write(output);

#!/usr/bin/env python3
"""Register received Water and Habitat Context with the current portable application."""
from __future__ import annotations

import argparse
import ast
import fcntl
import hashlib
import json
import os
from pathlib import Path
import tempfile

REQUIRED = (
    "model/water_context.py", "model/WATER_CONTEXT.md",
    "operator/water_context_service.py", "operator/WATER_CONTEXT_SERVICE.md",
    "operator/web/water_context.mjs", "operator/web/water_context_map.mjs",
    "operator/web/water_context.css", "operator/extensions/water-context.json",
    "water_context_cli.py", "WATER_CONTEXT_OPERATOR.md",
)
ROOT_FILES = ("water_context_cli.py", "WATER_CONTEXT_OPERATOR.md")


def sha(body):
    return hashlib.sha256(body).hexdigest()


def source_file(application, name):
    path = application
    for part in Path(name).parts:
        path = path / part
        if path.is_symlink():
            raise ValueError("Receive regular application source: " + name)
    if not path.is_file():
        raise ValueError("Receive the complete current application first; missing " + name)
    return path


def portable_source(source):
    """Append only missing owned roots to the actual ordered literal inventory."""
    tree = ast.parse(source, filename="model/portable.py")
    declared, last = [], None

    def sequence(node):
        if isinstance(node, ast.Name) and node.id == "APPLICATION_FILES":
            return list(declared)
        if isinstance(node, (ast.Tuple, ast.List, ast.Set)):
            values = []
            for item in node.elts:
                if isinstance(item, ast.Starred):
                    values.extend(sequence(item.value))
                elif isinstance(item, ast.Constant) and isinstance(item.value, str):
                    values.append(item.value)
                else:
                    raise ValueError("Portable application files must use literal names")
            return values
        if isinstance(node, ast.BinOp) and isinstance(node.op, ast.Add):
            return sequence(node.left) + sequence(node.right)
        if isinstance(node, ast.Call) and len(node.args) == 1 and not node.keywords:
            constructor = isinstance(node.func, ast.Name) and node.func.id in {"tuple", "list", "set"}
            unique = (isinstance(node.func, ast.Attribute) and node.func.attr == "fromkeys"
                      and isinstance(node.func.value, ast.Name) and node.func.value.id == "dict")
            if constructor or unique:
                return sequence(node.args[0])
        raise ValueError("Compose the current literal APPLICATION_FILES declaration")

    for node in tree.body:
        if isinstance(node, ast.Assign):
            targets, value = node.targets, node.value
        elif isinstance(node, ast.AnnAssign):
            targets, value = [node.target], node.value
        elif (isinstance(node, ast.AugAssign) and isinstance(node.target, ast.Name)
              and node.target.id == "APPLICATION_FILES"):
            if not isinstance(node.op, ast.Add):
                raise ValueError("Compose the current portable inventory operation")
            declared += sequence(node.value)
            last = node
            continue
        else:
            continue
        if any(isinstance(target, ast.Name) and target.id == "APPLICATION_FILES" for target in targets):
            if value is None:
                continue
            declared = sequence(value)
            last = node
    if last is None:
        raise ValueError("The current application has no portable APPLICATION_FILES inventory")
    missing = tuple(name for name in ROOT_FILES if name not in declared)
    if not missing:
        return source
    lines = source.splitlines(keepends=True)
    addition = "# Water and Habitat Context root command and operating guide.\nAPPLICATION_FILES += " + repr(missing) + "\n"
    prefix = "".join(lines[:last.end_lineno])
    if not prefix.endswith("\n"):
        prefix += "\n"
    updated = prefix + addition + "".join(lines[last.end_lineno:])
    ast.parse(updated, filename="model/portable.py")
    return updated


def compose(application):
    """Use installed shared hooks; the addon never supplies a replacement host."""
    bodies = {}
    for name in (*REQUIRED, "install_extensions.py", "operator/extension_registry.py",
                 "model/portable.py", "operator/server.py", "operator/web/app.mjs"):
        bodies[name] = source_file(application, name).read_bytes()
    for name in REQUIRED:
        if name.endswith(".py"):
            compile(bodies[name], str(application / name), "exec")
    descriptor = json.loads(bodies["operator/extensions/water-context.json"])
    if (descriptor.get("schema") != "upstate.operator-extension/v1"
            or descriptor.get("id") != "water-context"
            or descriptor.get("backend", {}).get("module") != "water_context_service"):
        raise ValueError("Receive the original Water and Habitat Context descriptor")
    host = application / "install_extensions.py"
    namespace = {"__name__": "_water_context_current_installer", "__file__": str(host)}
    exec(compile(bodies["install_extensions.py"], str(host), "exec"), namespace)
    if not callable(namespace.get("patch_server")) or not callable(namespace.get("patch_app")):
        raise ValueError("The installed extension owner must supply patch_server and patch_app")
    pending = {
        "operator/server.py": namespace["patch_server"](bodies["operator/server.py"].decode("utf-8")).encode("utf-8"),
        "operator/web/app.mjs": namespace["patch_app"](bodies["operator/web/app.mjs"].decode("utf-8")).encode("utf-8"),
        "model/portable.py": portable_source(bodies["model/portable.py"].decode("utf-8")).encode("utf-8"),
    }
    for name, body in pending.items():
        if name.endswith(".py"):
            compile(body, str(application / name), "exec")
    return bodies, pending


def install(application, *, dry_run=False):
    application = Path(application).resolve(strict=True)
    lock_root = application / ".locks"
    if lock_root.is_symlink():
        raise ValueError("The application lock directory is a file alias")
    lock_root.mkdir(exist_ok=True)
    lock_path = lock_root / "extension-install.lock"
    fd = os.open(lock_path, os.O_CREAT | os.O_RDWR | getattr(os, "O_NOFOLLOW", 0), 0o600)
    with os.fdopen(fd, "a+") as lock:
        fcntl.flock(lock, fcntl.LOCK_EX)
        original, pending = compose(application)
        changes = [name for name, body in pending.items() if body != original[name]]
        receipt = {
            "schema": "upstate.water-context-install/v1", "application": str(application),
            "dry_run": dry_run, "changed": changes, "retained_root_files": list(ROOT_FILES),
            "files": [{"path": name, "bytes": len(body), "sha256": sha(body),
                       "previous_sha256": sha(original[name])} for name, body in sorted(pending.items())],
            "dependencies": [{"path": name, "bytes": len(body), "sha256": sha(body)}
                             for name, body in sorted(original.items()) if name not in pending],
        }
        if dry_run or not changes:
            return receipt
        staged, applied = {}, []
        try:
            for name in changes:
                path = source_file(application, name)
                with tempfile.NamedTemporaryFile(dir=path.parent, prefix=".water-context-install-", delete=False) as out:
                    out.write(pending[name])
                    out.flush()
                    os.fsync(out.fileno())
                    staged[name] = Path(out.name)
                os.chmod(staged[name], path.stat().st_mode & 0o777)
            for name, expected in original.items():
                if source_file(application, name).read_bytes() != expected:
                    raise ValueError("Concurrent current source change: " + name)
            for name in changes:
                path = source_file(application, name)
                if path.read_bytes() != original[name]:
                    raise ValueError("Concurrent current source change: " + name)
                os.replace(staged[name], path)
                applied.append(name)
        except BaseException:
            # Restore only a source body still identical to this operation's write.
            for name in reversed(applied):
                path = source_file(application, name)
                if path.read_bytes() != pending[name]:
                    continue
                with tempfile.NamedTemporaryFile(dir=path.parent, prefix=".water-context-rollback-", delete=False) as out:
                    out.write(original[name])
                    out.flush()
                    os.fsync(out.fileno())
                    rollback = Path(out.name)
                os.chmod(rollback, path.stat().st_mode & 0o777)
                os.replace(rollback, path)
            raise
        finally:
            for path in staged.values():
                path.unlink(missing_ok=True)
        return receipt


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--application", default=str(Path(__file__).resolve().parent.parent))
    parser.add_argument("--dry-run", action="store_true")
    args = parser.parse_args(argv)
    print(json.dumps(install(args.application, dry_run=args.dry_run), indent=2, sort_keys=True))


if __name__ == "__main__":
    main()

/* Observed year and sampling-date context from retained agency-derived tables. */
export function parseCsv(text) {
  const rows=[]; let row=[],cell='',quoted=false;
  for(let i=0;i<text.length;i++){
    const c=text[i];
    if(quoted){if(c==='"'&&text[i+1]==='"'){cell+='"';i++;}else if(c==='"')quoted=false;else cell+=c;}
    else if(c==='"')quoted=true;
    else if(c===','){row.push(cell);cell='';}
    else if(c==='\n'||c==='\r'){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(v=>v!==''))rows.push(row);row=[];cell='';}
    else cell+=c;
  }
  if(quoted)throw Error('Incomplete CSV quotation');
  if(row.length||cell){row.push(cell);rows.push(row);}
  const columns=(rows.shift()||[]).map((c,i)=>i===0?c.replace(/^\uFEFF/,''):c);
  if(new Set(columns).size!==columns.length)throw Error('Duplicate CSV column');
  return rows.map(values=>{if(values.length!==columns.length)throw Error('CSV row width differs');return Object.fromEntries(columns.map((c,i)=>[c,values[i]]));});
}
const number=(value,label)=>{if(value===''||value==null||!Number.isFinite(Number(value)))throw Error('Missing or invalid '+label);return Number(value);};
const sum=values=>{let total=0,correction=0;for(const value of values){const y=value-correction,t=total+y;correction=(t-total)-y;total=t;}return total;};
const median=values=>{if(!values.length)return null;const s=[...values].sort((a,b)=>a-b),i=Math.floor(s.length/2);return s.length%2?s[i]:(s[i-1]+s[i])/2;};
const countDays=(start,end)=>Math.round((Date.parse(end+'T00:00:00Z')-Date.parse(start+'T00:00:00Z'))/86400000)+1;
const unique=(rows,key,label)=>{const seen=new Set();for(const row of rows){const id=key(row);if(seen.has(id))throw Error('Duplicate '+label+': '+id);seen.add(id);}};
export function assessObservedContext({annual,daily,dates,year=2023,gauge='02186702',windowStart='2023-04-05',windowEnd='2023-10-17'}) {
  unique(annual,r=>r.site+':'+r.period_start,'annual period');
  unique(daily,r=>r.site+':'+r.date,'daily observation');
  unique(dates,r=>r.gauge_id+':'+r.sampling_date,'study date');
  const start=year+'-01-01',end=year+'-12-31',expected=countDays(start,end);
  const groups=new Map();
  for(const row of annual){
    if(row.parameter_code!=='00060'||row.statistic_code!=='00003'||row.period_type!=='calendar_year')throw Error('Select original calendar-year daily-mean discharge summaries');
    const values=groups.get(row.site)||[];values.push(row);groups.set(row.site,values);
  }
  const stationContext=[];
  for(const [site,rows] of groups){
    const target=rows.find(r=>r.period_start===start&&r.period_end===end);if(!target)continue;
    const complete=rows.filter(r=>number(r.valid_days,'valid days')===number(r.expected_days,'expected days'));
    const reference=complete.filter(r=>r!==target);
    const valid=number(target.valid_days,'target valid days'),isComplete=valid===expected;
    const referenceMedian=median(reference.map(r=>number(r.mean_cfs,'reference annual mean')));
    const targetMean=valid?number(target.mean_cfs,'target mean'):null;
    stationContext.push({
      site,site_name:target.site_name,year,valid_days:valid,expected_days:expected,complete_year:isComplete,
      complete_reference_years:reference.map(r=>r.period_start.slice(0,4)).sort(),
      complete_year_count:complete.length,observed_mean_cfs:targetMean,
      complete_year_runoff_mm:isComplete&&target.complete_period_runoff_mm!==''?number(target.complete_period_runoff_mm,'runoff'):null,
      reference_median_annual_mean_cfs:referenceMedian,
      mean_ratio_to_other_complete_years:isComplete&&referenceMedian>0?targetMean/referenceMedian:null,
      ascending_mean_rank:isComplete?1+complete.filter(r=>number(r.mean_cfs,'annual mean')<targetMean).length:null,
      approved_days:number(target.approved_days,'approved days'),provisional_days:number(target.provisional_days,'provisional days'),
      estimated_days:number(target.estimated_days,'estimated days'),revised_days:number(target.revised_days,'revised days'),
      reference_quality:reference.map(r=>({year:r.period_start.slice(0,4),approved_days:Number(r.approved_days),provisional_days:Number(r.provisional_days),estimated_days:Number(r.estimated_days),revised_days:Number(r.revised_days)}))
    });
  }
  stationContext.sort((a,b)=>a.site.localeCompare(b.site));
  const selectedAnnual=annual.find(r=>r.site===gauge&&r.period_start===start&&r.period_end===end);
  if(!selectedAnnual)throw Error('Selected gauge lacks its annual summary');
  const series=daily.filter(r=>r.site===gauge&&r.date>=start&&r.date<=end);
  if(series.length!==expected)throw Error('The sampling-context reference requires a complete original daily year');
  const index=new Map(series.map(r=>[r.date,r])),values=series.map(r=>number(r.reported_mean_cfs,'daily mean'));
  const annualMean=sum(values)/series.length,reportedMean=number(selectedAnnual.mean_cfs,'annual mean');
  if(Math.abs(annualMean-reportedMean)>1e-10*Math.max(1,Math.abs(reportedMean)))throw Error('Original daily values differ from the annual mean');
  const threshold=number(selectedAnnual.p95_daily_cfs,'annual p95');
  const selectedDates=dates.filter(r=>r.gauge_id==='USGS-'+gauge&&r.sampling_date>=start&&r.sampling_date<=end);
  if(!selectedDates.length)throw Error('Select the retained sampling-date cohort');
  for(const row of selectedDates){
    const original=index.get(row.sampling_date);
    if(!original||number(original.reported_mean_cfs,'original mean')!==number(row.same_date_mean_cfs,'sample-date mean')||
      original.source_id!==row.same_date_flow_source_id||original.source_record_index!==row.same_date_flow_source_record_index||
      original.source_values_index!==row.same_date_flow_source_values_index)throw Error('Sampling-date flow does not match its retained original daily record');
  }
  const summarize=rows=>{const peak=rows.filter(r=>number(r.reported_mean_cfs,'flow')>=threshold),total=sum(rows.map(r=>Number(r.reported_mean_cfs)));
    return {valid_days:rows.length,days_at_or_above_annual_p95:peak.length,
      fraction_of_observed_volume_at_or_above_annual_p95:total>0?sum(peak.map(r=>Number(r.reported_mean_cfs)))/total:null,
      dates_at_or_above_annual_p95:peak.map(r=>r.date)};};
  const study=series.filter(r=>r.date>=windowStart&&r.date<=windowEnd);
  if(study.length!==countDays(windowStart,windowEnd))throw Error('Study-window daily observations are incomplete');
  const sampled=selectedDates.map(r=>Number(r.same_date_mean_cfs));
  const samplingContext={gauge_id:'USGS-'+gauge,year,annual_p95_daily_mean_cfs:threshold,
    annual_mean_cfs:annualMean,annual:summarize(series),study_window:{start:windowStart,end:windowEnd,...summarize(study)},
    sampled_unique_dates:selectedDates.length,sampled_dates_at_or_above_annual_p95:sampled.filter(v=>v>=threshold).length,
    sampled_mean_daily_flow_cfs:sum(sampled)/sampled.length,sampled_median_daily_flow_cfs:median(sampled),
    sampled_min_daily_flow_cfs:Math.min(...sampled),sampled_max_daily_flow_cfs:Math.max(...sampled),
    prior_three_day_mean_at_or_above_annual_p95:selectedDates.filter(r=>Number(r.prior_3d_mean_cfs)>=threshold).map(r=>r.sampling_date),
    prior_seven_day_mean_at_or_above_annual_p95:selectedDates.filter(r=>Number(r.prior_7d_mean_cfs)>=threshold).map(r=>r.sampling_date),
    source_dates:selectedDates.map(r=>({date:r.sampling_date,flow_source_id:r.same_date_flow_source_id,values_index:Number(r.same_date_flow_source_values_index),record_index:Number(r.same_date_flow_source_record_index),activity_count:Number(r.source_activity_count),chlorophyll_sites:r.chla_sites,microcystin_sites:r.micro_sites}))};
  return {schema:'upstate.observed-calibration-context/v1',reference_year:year,reference_rule:'Median annual mean of other fully observed years at the same original gauge; target year excluded',
    units:{flow:'ft3/s',runoff:'mm',volume_fraction:'dimensionless'},
    station_context:stationContext,sampling_context:samplingContext};
}
export function contextCsv(rows) {
  const columns=['site','site_name','year','valid_days','expected_days','complete_year','complete_year_count','complete_reference_years','observed_mean_cfs','complete_year_runoff_mm','reference_median_annual_mean_cfs','mean_ratio_to_other_complete_years','ascending_mean_rank','approved_days','provisional_days','estimated_days','revised_days'];
  const cell=value=>{const text=value==null?'':Array.isArray(value)?value.join('|'):String(value);return /[",\r\n]/.test(text)?'"'+text.replaceAll('"','""')+'"':text;};
  return [columns.join(','),...rows.map(row=>columns.map(key=>cell(row[key])).join(','))].join('\n')+'\n';
}

export function renderContextMarkdown(result) {
  const s=result.sampling_context,rows=result.station_context,fmt=(v,n=2)=>v==null?'—':Number(v).toFixed(n),pct=v=>fmt(v*100,2)+'%';
  const eighteen=rows.find(r=>r.site==='02186702');
  const stationLines=rows.map(r=>'| '+r.site+' | '+r.site_name+' | '+r.valid_days+'/'+r.expected_days+' | '+fmt(r.observed_mean_cfs)+' | '+fmt(r.reference_median_annual_mean_cfs)+' | '+(r.mean_ratio_to_other_complete_years==null?'—':pct(r.mean_ratio_to_other_complete_years))+' | '+(r.ascending_mean_rank==null?'—':r.ascending_mean_rank+'/'+r.complete_year_count)+' |');
  return [
    '# Observed flow context for the Upper Savannah modelling work','',
    '## Decisions supported by these observations','',
    'The completed agency capture provides 2020–2025 daily flows and exact laboratory sampling dates. This assessment uses each gauge’s own complete annual observations to place 2023 in context, and measures which flow conditions the Eighteenmile lake-study dates represent. The calculation retains the original source-record references and quality counts.','',
    'At Eighteenmile Creek below Pendleton (USGS 02186702), the 2023 annual mean was '+fmt(eighteen.observed_mean_cfs,5)+' ft³/s, '+pct(eighteen.mean_ratio_to_other_complete_years)+' of the median annual mean in its other complete observed years. Compare this with the individual headwater rows below when selecting climate years and gauged catchments for regional model evaluation.','',
    '## Gauge-specific annual context','',
    'The reference is the median of the other fully observed annual means at the same gauge. The 2023 target is excluded from its own reference. Rank 1 is the lowest annual mean among that gauge’s complete years in this retained six-year record. Partial periods retain their observed mean and coverage; their annual ratio, annual runoff and rank remain empty. The JSON retains the approval, provisional, estimated and revised counts for the target and every reference year.','',
    '| USGS site | Original station name | 2023 valid days | 2023 mean, ft³/s | Other-year median, ft³/s | 2023/reference | Ascending rank |',
    '| --- | --- | ---: | ---: | ---: | ---: | ---: |',...stationLines,'',
    'Use the original gauge locations, contributing areas and published operating context when selecting a comparison. In particular, the two source records labelled powerhouse retain their separate station identities. The inventory spans four HUC8 query areas; each spatial comparison also carries the selected model-domain and gauge-catchment geometry.','',
    '## Sampling dates and observed high-flow periods','',
    'The retained study cohort has '+s.sampled_unique_dates+' unique 2023 dates. The original daily-flow reference contains '+s.annual.valid_days+' days. Its annual 95th percentile of daily mean flow is '+fmt(s.annual_p95_daily_mean_cfs,1)+' ft³/s.','',
    '- '+s.annual.days_at_or_above_annual_p95+' days meet or exceed that threshold and account for '+pct(s.annual.fraction_of_observed_volume_at_or_above_annual_p95)+' of the observed annual discharge volume.',
